const SKILLS=[{"key": "music", "p": "music", "name": "Музыка", "short": "биты, запись, сведение", "why": "Твоё дело. Здесь растёт не «талант», а руки: чем больше законченных повторов, тем лучше звук.", "rows": [["beats", "rec"], ["mix"]], "parents": {"mix": ["beats", "rec"]}, "skills": [{"id": "beats", "name": "Биты", "desc": "Собирать бит быстро и доводить до конца.", "fy": "Пиши много плохих битов — из сотого выйдет хороший.", "why": "Арсен: проигрывай в малом тысячу раз, чтобы победить в большом.", "tiers": [{"n": 1, "mode": "days", "days": 21, "title": "8 тактов в день", "how": "Каждый день хотя бы 8 тактов: ударные + бас или мелодия. Не нравится — всё равно сохрани (или экспорт в WAV).", "daily": "8 тактов бита"}, {"n": 2, "mode": "steps", "title": "10 законченных битов", "how": "Законченный — значит есть начало, развитие и конец, а не луп.", "steps": ["Бит 1", "Бит 2", "Бит 3", "Бит 4", "Бит 5", "Бит 6", "Бит 7", "Бит 8", "Бит 9", "Бит 10"]}, {"n": 3, "mode": "steps", "title": "Свой звук", "how": "Найти, чем твои биты отличаются от чужих.", "steps": ["Выбрать 3 референса (Кай Энджел, Лил Пип, Tame Impala…) и разобрать, из чего их звук", "Сделать бит «в духе» каждого", "Сделать бит, где смешаны все три", "Дать послушать 3 людям и записать, что зацепило"]}]}, {"id": "rec", "name": "Запись", "desc": "Записывать голос, который не стыдно слушать.", "fy": "Начни с записи, когда дома никого нет. Потом — при домашних.", "why": "Запись хромает, потому что было мало дублей. Это решается количеством.", "tiers": [{"n": 1, "mode": "days", "days": 21, "title": "Один дубль в день", "how": "Куплет или 4 строчки — один дубль. Переслушать завтра, не сегодня.", "daily": "Один дубль голоса"}, {"n": 2, "mode": "steps", "title": "Куплет, который нравится", "how": "", "steps": ["Записать куплет 5 разными подачами (тихо, громко, шёпот, речитатив, распев)", "Выбрать лучшую подачу", "Записать 10 дублей этой подачи и собрать лучший", "Записать бэки и даблы"]}, {"n": 3, "mode": "once", "title": "Трек целиком за один день", "how": "Бит готов — запиши весь вокал за день, от первого куплета до последнего припева."}]}, {"id": "mix", "name": "Сведение", "desc": "Чтобы хорошие идеи звучали в хорошем качестве.", "fy": "Хорошие мысли — в хорошем качестве. Сведение решает.", "why": "Арсен: главная проблема хорошего дела — организация и качество подачи.", "tiers": [{"n": 1, "mode": "steps", "title": "Основы", "how": "Учиться по одному уроку и сразу повторять на своём треке.", "steps": ["Урок: громкость и панорама — повторить на своём наброске", "Урок: эквалайзер (убрать лишний низ) — повторить", "Урок: компрессор на вокал — повторить", "Урок: реверб и дилей — повторить"]}, {"n": 2, "mode": "days", "days": 14, "title": "Свести один набросок", "how": "В день — свести один набросок хотя бы до «не стыдно скинуть».", "daily": "Сведение одного наброска"}, {"n": 3, "mode": "steps", "title": "Сравнение с референсом", "how": "", "steps": ["Выбрать референс-трек из любимых", "Свести свой трек и сравнить громкость и баланс", "Исправить 3 главных отличия", "Дать послушать на телефоне, в наушниках и в колонке"]}]}]}, {"key": "osnova", "p": "head", "name": "Основа", "short": "личная ответственность", "why": "Скрытый слой под всеми путями. Без личной ответственности любой рост рассыпается: персональная сила = ответственность × честность.", "skills": [{"id": "resp", "name": "Личная ответственность", "desc": "Позиция творца: «я это создал — какие выводы?»", "why": "Арсен: персональная сила = степень ответственности за жизнь × честность взгляда на неё. Жертва говорит «это со мной произошло», творец — «я это создал, какие выводы?». Меньше ответственности → меньше ресурса → ещё меньше ответственности. Это фундамент под всеми путями.", "tiers": [{"n": 1, "mode": "steps", "title": "Язык хозяина", "how": "Три вечера подряд писать 3 строки дня с «я» и глаголом от себя: «я не дописал», а не «не получилось».", "daily": "", "goal": "Сделать все шаги", "chapter": [{"text": "«Это со мной произошло» против «я это создал — какие выводы?». Первая позиция не требует думать, поэтому мозг её любит. Вторая даёт силу менять.", "title": "Жертва и творец"}, {"text": "«Я» в именительном падеже и глагол от себя: «я позволил себя обмануть», «я не проверил договор». Жертва говорит страдательно: «меня обманули, меня провели».", "title": "Язык хозяина"}, {"text": "Не оценивать ситуацию, а спросить: что я сделал не так? что мог сделать лучше? что сделаю в следующий раз?", "title": "Ключевой вопрос"}], "steps": ["Прочитать свиток: жертва и творец", "3 вечера подряд — три строки дня с «я» и глаголом от себя", "Поймать за день одну фразу-жертву («меня подставили», «так вышло») и переписать", "Записать, что изменилось"]}, {"n": 2, "mode": "steps", "title": "Правило 10 факторов", "how": "После неудачи выписать 10 своих причин. Пока фаза «Энергия» — хотя бы 3.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"text": "После каждой неудачной встречи Арсен выписывал минимум 10 причин, где облажался сам. Коллеги обсуждали, «какие вокруг долбоёбы». Вырос он, а не они.", "title": "10 факторов"}, {"text": "Результат — единственная проверка. Отказ — сигнал поменять подход, текст или подготовку, а не «все плохие».", "title": "Не получилось — было неправильно"}], "steps": ["После ближайшей неудачи выписать 10 своих причин (в фазе «Энергия» — хотя бы 3)", "Отметить 3, которые исправишь", "Создать задачу «Разбор срыва: …» — за неё опыт", "Повторить после следующей неудачи"]}, {"n": 3, "mode": "steps", "title": "Я выбираю… потому что…", "how": "Одна хроническая жалоба — честно дописать, что она тебе даёт.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"text": "«Я выбираю прокрастинацию, потому что снимаю с себя риск ошибки». Это должно отзываться внутри, а не быть отговоркой.", "title": "Честность"}, {"text": "«Меня должны уважать» → «каким мне стать, чтобы уважали?». Требование к миру превращается в задачу себе.", "title": "Скрытое «мир должен»"}], "steps": ["Взять одну хроническую жалобу (откладываю звонки, прокрастинация)", "Дописать честно: «я выбираю это, потому что это мне даёт…»", "Написать три «я имею право…»", "Сделать одно действие, которое меняет выбор"]}], "fy": "Военкомат, пробная FL, общий ноут — вопрос всегда «что могу я»."}, {"id": "mistake", "name": "Право на ошибку", "desc": "Ошибка — это попытка, а не приговор.", "why": "Арсен: школа научила, что ошибка отнимает у результата. В жизни нет: в боксе шесть раундов мимо — один удар, нокаут. Не ошибается тот, кто ничего не делает, но его ошибка фундаментальна. Для работы и музыки это главное: каждый отказ — попытка.", "tiers": [{"n": 1, "mode": "steps", "title": "Ошибка = попытка", "how": "5 дней: утром «я имею право ошибаться» и одна попытка там, где страшно ошибиться.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"text": "Сказать себе: я имею право ошибаться, быть неправым, остаться в дураках, быть посмешищем. Осмеяние — не смерть.", "title": "Я имею право ошибаться"}, {"text": "Выиграл в спарринге — проиграл в бою. Слабые места закрывают на тренировке, а не в финале.", "title": "Чтобы запомнилось"}], "steps": ["5 дней подряд утром сказать себе: «Я имею право ошибаться»", "Каждый из этих дней — одна попытка там, где страшно (написать, позвонить, спросить)", "После каждой — строка в журнал: что понял"]}, {"n": 2, "mode": "steps", "title": "Отказ = форма B", "how": "После каждого отказа — одна строка: «почему, по-моему, отказали / что поменяю».", "daily": "", "goal": "Сделать все шаги", "steps": ["После каждого отказа (вакансия, человек) — строка «почему отказали / что поменяю»", "Оформить задачей «Разбор отказа: …» — за неё опыт", "Сделать так 5 раз"]}, {"n": 3, "mode": "steps", "title": "Пётр за 300", "how": "Сходить на 5 собесов, в том числе не самых желанных — как на тренировку.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"text": "На первом этапе пробовать как можно больше: собесы, звонки, показать трек — навык растёт от количества. Не самый желанный собес — бесплатная тренировка.", "title": "Чужая точка"}], "steps": ["Пройти 5 собеседований, в том числе не самых желанных", "После каждого — 3 вывода", "Выбрать одну вещь, которую улучшишь к следующему"]}], "fy": "Каждый отказ на собесе или «не зашёл трек» — попытка, а не приговор."}, {"id": "honest", "name": "Честность с собой", "desc": "Видеть, где ты на самом деле, без утешений.", "why": "Сила растёт не от хорошего к лучшему, а от невыносимого к лучшему. Пока не признаёшь, где ты сейчас, двигаться некуда. Самооценка раньше способностей: сначала честная карта, потом путь.", "tiers": [{"n": 1, "mode": "steps", "title": "Мои максимумы", "how": "По каждому из 5 путей: что для меня «0», что «100» и где я сейчас (1–10).", "daily": "", "goal": "Сделать все шаги", "steps": ["По каждому пути записать: что для меня «0», что «100», где я сейчас (1–10)", "Выбрать один путь, который тянет вниз остальные", "Одно дело на неделю в этот путь", "Пересмотреть через месяц"]}, {"n": 2, "mode": "steps", "title": "Два хочу", "how": "Проверить цели: я делаю шаги или просто не отказался бы?", "daily": "", "goal": "Сделать все шаги", "steps": ["Выписать 5 своих целей", "Про каждую: я делаю шаги или просто не отказался бы?", "Вычеркнуть «не отказался бы»", "Для оставшейся — шаг на завтра"]}, {"n": 3, "mode": "steps", "title": "Тюрьма на год", "how": "Письменно: как бы ты использовал год взаперти? Одно дело оттуда — на эту неделю.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"text": "Представь, что сел на год. Читать, качаться, медитировать, осмыслить жизнь. Любую «потерянную» ситуацию можно так же развернуть в пользу.", "title": "Любую потерянную ситуацию"}], "steps": ["Письменно ответить: как бы использовал год взаперти", "Выбрать оттуда одно дело", "Сделать его на этой неделе"]}], "fy": "Сколько треков ты реально закончил за месяц? С этого начинается рост."}, {"id": "conditions", "name": "Менять условия", "desc": "Не ругать клубнику — поменять почву.", "why": "Ты — результат условий. Не бороться с условиями, а менять их: не просить мир подстроиться, а решить на своей стороне. Сил на жалобу хватает — хватит и на решение.", "tiers": [{"n": 1, "mode": "steps", "title": "Решай на своей стороне", "how": "Три раздражителя — к каждому своё действие вместо жалобы.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выписать 3 вещи, которые раздражают в людях или мире", "К каждой — действие на своей стороне (беззвучный режим, отписка, уйти раньше)", "Сделать все три"]}, {"n": 2, "mode": "steps", "title": "Отдых — после дела", "how": "7 дней: лента, игры и сериалы только после закрытого блока.", "daily": "", "goal": "Сделать все шаги", "steps": ["7 дней: развлечения только после закрытого обязательного блока", "Вечером отметить, получилось ли", "Записать, как изменилась энергия"]}, {"n": 3, "mode": "steps", "title": "Не ругай клубнику", "how": "Одна слабость — найти условия, которые её кормят, и поменять одно.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выбрать одну свою слабость", "Найти условия, которые её кормят (среда, люди, время)", "Поменять одно условие и прожить так неделю"]}], "fy": "Ноут на столе с утра, сладкое не покупать — меняй условия, а не уговаривай себя."}, {"id": "facefear", "name": "Победа над страхом", "desc": "Делать страшное маленькими шагами и отмечать победы.", "why": "Страх не уходит от мыслей — только от действия. Каждое страшное дело, записанное как победа, делает следующее легче. Агрессия — это экспансия, а не насилие: сказать прямо — не значит напасть.", "tiers": [{"n": 1, "mode": "steps", "title": "Сказать в лицо", "how": "За неделю 3 раза прямо и спокойно сказать, что не устраивает — вместо молчания и жалоб потом.", "daily": "", "goal": "Сделать все шаги", "steps": ["3 раза за неделю прямо и спокойно сказать, что не устраивает (кафе, сервис, знакомый)", "Не молчать и не жаловаться потом", "После каждого — строка в журнал «победа над страхом»"]}, {"n": 2, "mode": "steps", "title": "Перепрограммирование", "how": "Одна автоматическая уступка — три раза за неделю сделать по-новому.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выбрать одну автоматическую уступку (промолчать, согласиться, «извините» без вины)", "Заранее представить момент", "3 раза за неделю сделать по-новому"]}, {"n": 3, "mode": "steps", "title": "Пройти боль насквозь", "how": "Одна спрятанная болевая точка — три раза сознательно пойти туда, где её видно.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выбрать одну спрятанную болевую точку", "За неделю 3 раза сознательно пойти туда, где её видно", "Записать, что стало легче"]}], "fy": "Твой главный навык: звонки, собеседования, показать трек."}, {"id": "hormones", "name": "Гормональный пульт", "desc": "Понимать, что сейчас рулит тобой, и брать нужный рычаг.", "why": "Настроение, воля, фокус и смелость — это работа гормонов. Мозг не отличает картинку от жизни и замечает перемены только через 14–16 дней. Кто понимает свой пульт, тот управляет собой, а не живёт на случайных всплесках.", "tiers": [{"n": 1, "mode": "steps", "title": "Карта гормонов", "how": "Прочитать 10 портретов в «Знаниях», найти 2–3 проседающих гормона и для каждого выбрать по одному рычагу: тело, голова, люди.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"practice": "Отметь не один гормон, а связку: например, мало сна → кортизол ↑ → тестостерон ↓.", "text": "Нет одной волшебной кнопки. Система или здорова, или перекошена целиком, как машина со спущенным колесом. Ищи причину причин, а не лечи хвост.", "title": "Всё связано со всем"}, {"practice": "Посчитай свои шаги за сегодня.", "text": "Гормоны разносятся кровью и лимфой. Без движения на ногах они не доходят до цели. Минимум — 6–10 км ходьбы и 50–100 приседаний в день.", "title": "Сначала логистика"}, {"practice": "Три раза в день спроси себя: что я сейчас чувствую в теле?", "text": "Каждое ощущение — работа гормона. Научись узнавать их по отдельности — появится пульт: вспомнил ощущение — запустил процесс.", "title": "Ощущение = гормон"}], "steps": ["Прочитать 10 портретов гормонов в «Знаниях»", "Отметить 2–3, которые у меня проседают (по признакам «когда низкий»)", "Для каждого выбрать по одному рычагу: тело, голова, люди", "Записать эти рычаги во «Входящие» и сделать", "Через 16 дней (17.10) перечитать и сравнить"]}, {"n": 2, "mode": "days", "title": "Язык тела победителя", "how": "Неделю держать геометрию победителя: грудь раскрыта, плечи назад, подбородок вверх, о будущем думать, глядя в небо. Утром — 5 фраз. Вечером — одно «не думал, что смогу, но сделал».", "daily": "", "goal": "7 дней подряд", "days": 7, "chapter": [{"practice": "Выбери на неделю планку, от которой чуть страшно, но реально.", "text": "Тестостерон растёт, когда борьба напряжённая, но победа возможна. Слишком легко или слишком тяжело — его нет. Главный навык — нащупывать этот коридор и ставить себе посильную планку.", "title": "Коридор борьбы"}, {"practice": "Две минуты позы победителя перед важным разговором.", "text": "Тело не отличает игру от реальности. Расправленная грудь, подбородок вверх и взгляд в небо за 10 минут сдвигают тестостерон и кортизол. Занимай столько места, сколько хочется.", "title": "Поза меняет гормоны"}, {"practice": "Неделя без новостей.", "text": "Новости и сводки о том, на что не влияешь, мозг считает ежедневным поражением. Сузить внимание до того, за что отвечаешь сам.", "title": "Фокус на своём"}], "steps": ["Утром вслух: «Я могу. Я достоин. Я хочу. Я беру. Я делаю.»", "Весь день: грудь раскрыта, плечи назад, подбородок вверх", "О планах думать, глядя в небо, а не в пол", "Вечером записать одно «не думал, что смогу, но сделал»", "7 дней не читать новости и не смотреть сводки", "Всё бесит — важные решения и разговоры отложить до сна и еды", "Итог недели: что изменилось в настроении и уверенности"]}, {"n": 3, "mode": "days", "title": "16 дней новой колеи", "how": "Мозг начинает перестраиваться после 14–16 дней. 16 дней подряд: 6+ км ходьбы и 50+ приседаний, утренний свет, живое общение каждый день, телефон без уведомлений. Потом сравнить карту гормонов.", "daily": "", "goal": "16 дней подряд", "days": 16, "chapter": [{"practice": "Не бросать раньше 16-го дня.", "text": "Тело держится за привычную колею. Новую надо наработать — и тогда она сама работает на результат. Меньше двух недель мозг считает случайностью.", "title": "Сначала гомеостаз, потом результат"}, {"practice": "Убрать один постоянный допинг на все 16 дней.", "text": "Выгоднее вернуть чувствительность рецепторов, чем гнать выработку. Она возвращается только долгим отдыхом от стимула: без пиков кайфа, кофе-допинга, громкого шума.", "title": "Чувствительность важнее количества"}], "steps": ["Каждый день 6+ км ходьбы (около 8 000 шагов)", "Каждый день 50+ приседаний без веса", "Утром 10 минут дневного света в глаза", "Каждый день живой разговор с человеком, с которым на одной волне", "Уведомления и звук телефона выключены", "Эмоции не держать: петь, смеяться, двигаться", "Тревога — спросить «где опасность?» и подвигаться", "16-й день: перечитать карту гормонов и сравнить"], "rank": "B"}], "fy": "Тоска, лень днём и тяга к сладкому — это гормоны. Ими можно рулить."}], "rows": [["resp", "mistake"], ["honest", "conditions", "hormones"], ["facefear"]], "parents": {"conditions": ["resp", "mistake"], "facefear": ["honest", "conditions"], "honest": ["resp"], "hormones": ["mistake"]}}, {"key": "mental", "p": "head", "name": "Ментал", "short": "ум, характер, решения", "why": "Арсен считает этот путь самым важным. Всё остальное умножается на ум: «тупой и трусливый беспомощен при любых возможностях». Вместе с Телом это база: если ты здоров, смел и умён, остальное дело времени.", "skills": [{"id": "journal", "name": "Журнал сделанного", "desc": "Каждый вечер от руки записывать, что реально сделал.", "why": "Арсен 2–3 недели записывал каждое сделанное действие и сказал: «никогда в жизни так хорошо не работал». Журнал показывает дела, а не планы. Опыт в игре тоже даётся только за дела.", "tiers": [{"n": 1, "mode": "days", "title": "3 строки сделанного + план на завтра", "how": "Вечером 3 строки: что я сегодня сделал (только дела). Потом всё, что крутится в голове, — во «Входящие», и выбрать 3 дела на завтра.", "daily": "Вечер 3 минуты: что сделал + 3–5 дел на завтра", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Вечером есть что записать.", "practice": "Три строки в тетради перед сном. Мелочь тоже считается, если сделана.", "text": "Не планы, не намерения, не «хотел». Только то, что физически сделано. «Вас не существует за пределами ваших действий: посмотрите, что вы сделали, — это и есть вы».", "title": "Только сделанное"}, {"practice": "Одна тетрадь — для журнала и для конспектов навыков.", "text": "Арсен записывал важное от руки в блокнот, а бытовое — в телефон. Рукой запоминается лучше, чем с экрана.", "title": "От руки"}, {"check": "Журнал читать приятно.", "practice": "Не пиши, чего не сделал. Только сделанное.", "text": "Никогда себя не обесценивать. Относись к себе как к сыну: что сказал бы ему, то и себе.", "title": "Без самокритики"}, {"check": "Утром план уже есть.", "practice": "Всё, что крутится, — одной строкой во Входящие. Потом 3–5 дел на завтра, не больше.", "text": "Ваагн: всё незакрытое жрёт энергию фоном. Перед сном часто крутится тоска и «ничего не сделал». Выписал — мозгу не надо держать это ночью.", "title": "Выгрузить голову перед сном"}]}, {"n": 2, "mode": "days", "title": "+ вопрос «делом или словами?»", "how": "Журнал + одна строка: где сегодня добыл значимость словами", "daily": "Журнал + где добыл значимость словами", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Замечаешь это прямо в моменте.", "practice": "Одна строка в журнале: где сегодня я получил значимость словами, а не делом.", "text": "Чувство важности можно добывать делом, а можно словами: спорить, обесценивать, разоблачать, рассказывать о планах. Слова дают ту же награду без усилия, как наркотик. «Приучишь себя добывать значимость словами — не сможешь добывать её действиями».", "title": "Фарм значимости"}, {"practice": "Поймал себя на рассказе о планах — отметь в журнале.", "text": "Рассказал о плане — мозг уже получил награду, и делать не хочется. Поэтому о квестах и планах молчим, пока нет результата.", "title": "Молчание до результата"}, {"practice": "Раз в неделю сравни, что заявлял и что сделал.", "text": "Сверка: что я вчера собирался сделать и что сделал. Не для самобичевания, а чтобы видеть свою реальную скорость.", "title": "Заявил — сделал"}]}, {"n": 3, "mode": "days", "title": "Дневник побед", "how": "Раз в неделю дописать главные победы, утром перечитывать 10 лучших", "daily": "Журнал + 10 лучших побед по утрам", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Утром есть на что опереться.", "practice": "Выписать свои 10 и 10, обновлять раз в неделю.", "text": "Из «Тестостерон Релиза»: 10 главных побед и 10 поступков, за которые себя уважаешь. Перечитывать утром.", "title": "10 главных побед"}, {"practice": "Раз в месяц: что я умею сейчас, чего не умел год назад.", "text": "Самооценка поднимается своими победами и сравнением с собой год назад. Сравнение с другими — «вор радости».", "title": "Сравнение только с собой"}, {"practice": "Утром одна строка: чем я доволен в себе прямо сейчас.", "text": "Смысл достижений — испытать состояние. Но быть довольным собой, радоваться жизни и быть уверенным можно уже сейчас.", "title": "Состояние бесплатно"}]}], "fy": "Ты держишь дела в голове — журнал их выгружает."}, {"id": "morning", "name": "Утро", "desc": "Утренний ритуал: день начинается с плана и цели, а не с ленты.", "why": "Ваагн: ночью мозг «чистит кэш», утром ему надо напомнить, зачем ты всё это делаешь. Арсен: лента с утра — быстрый дофамин, он крадёт энергию на весь день. Лимарев: привычку легче держать, когда она привязана к одному моменту дня.", "tiers": [{"n": 1, "mode": "days", "title": "Ритуал без телефона", "how": "Стакан воды, 5 минут зарядки (отжимания, приседания, пресс — каждый день на 1 раз больше), посмотреть список дел с вечера и прочитать заметку 🎯 цели месяца. Только потом телефон.", "daily": "Утро: вода → зарядка → план и цель → потом телефон", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Первые 20 минут дня без ленты.", "practice": "Телефон на ночь заряжается не у кровати (привычка «Сон»). Утром берёшь его после плана.", "text": "Лента с утра — быстрый дофамин: день начинается с чужих целей, и дальше тянет к ещё одной порции.", "title": "Почему не телефон первым"}, {"check": "Утром не гадаешь, с чего начать.", "practice": "Открыть игру на «Сегодня» и выбрать первое дело.", "text": "План составлен вечером (привычка «Вечер 3 минуты»). Утром голова ещё не соображает — думать не надо, только посмотреть.", "title": "План уже готов"}, {"check": "Без подсказки называешь цель месяца.", "practice": "Прочитать цель месяца на экране «Сегодня».", "text": "Цель месяца каждое утро перед глазами — мозгу надо напоминать, куда идём.", "title": "Зачем"}, {"check": "Число растёт.", "practice": "Запомни вчерашнее число и сделай на 1 больше.", "text": "Отжимания — это и твоя цель месяца: 20 подряд. Каждый день на один раз больше — «лёгкий соперник».", "title": "Зарядка растёт на 1"}]}, {"n": 2, "mode": "days", "title": "+ медитация 5 минут", "how": "После воды и зарядки сесть, закрыть глаза и 5 минут следить за дыханием. Когда станет привычкой — дольше.", "daily": "Утро + медитация 5 минут", "goal": "21 день практики", "days": 21}, {"n": 3, "mode": "days", "title": "+ «свиток зачем»", "how": "Перечитать цепочку смыслов (цель месяца → зачем она мне в жизни) и 10 своих главных побед из журнала.", "daily": "Утро + «свиток зачем»: цель месяца и 10 побед", "goal": "21 день практики", "days": 21}], "fy": "Ты встаёшь в 8 — первые 15 минут без телефона задают день."}, {"id": "calm", "name": "Торможение", "desc": "Умение успокоить разогнанную голову.", "why": "Прокрастинация часто не от лени, а от «разгона»: мыслей так много, что ничего не начать. Арсен лечит это дыханием, тупым ручным трудом и ходьбой, а не кофе.", "tiers": [{"n": 1, "mode": "days", "title": "«Дышу ли я?» — 3 раза в день замедлить дыхание", "how": "Медленно и глубоко носом, минуту. И перед сном.", "daily": "«Дышу ли я?» 3 раза в день", "goal": "", "days": 21, "chapter": [{"check": "Замечаешь, что задержал дыхание.", "practice": "Медленно и глубоко носом минуту. Утром, днём, перед сном.", "text": "Арсен: прокрастинация часто от разгона — мыслей так много, что ничего не начать. Кофе делает хуже. Нужно затормозить.", "title": "Разгон, а не лень"}, {"practice": "Когда накрыло — 1 минута смотреть в окно на одну точку.", "text": "Смотреть на неподвижное — вода, дерево — и сдувать каждую тревогу выдохом.", "title": "Спешка"}]}, {"n": 2, "mode": "days", "title": "Тупой труд 30 минут", "how": "Уборка, стирка, готовка руками — однообразное дело без экрана.", "daily": "Тупой ручной труд 30 минут", "goal": "", "days": 21, "chapter": [{"practice": "30 минут без экрана. Можно совместить с «Уборкой 15 минут».", "text": "Главное лекарство от «сверхбдительности» у Арсена: однообразная ручная работа — уборка, стирка, готовка, дрова. Голова отдыхает.", "title": "Тупой труд"}]}, {"n": 3, "mode": "days", "title": "Перезагрузка при разгоне", "how": "Лечь на пол, руки под голову: «сегодня я в безопасности». 15–20 минут тишины.", "daily": "Перезагрузка при разгоне", "goal": "", "days": 21, "chapter": [{"practice": "15–20 минут, когда день развалился на ленту и еду. Это не лень, а разгон.", "text": "Лечь на пол, руки под голову, закрыть глаза: «сегодняшний день закончится без происшествий, сегодня я в безопасности». Представить, что мозг охлаждают кулеры.", "title": "Сегодня я в безопасности"}]}], "fy": "Тревога и «башка нагревается» — это разгон. Тормоза тренируются."}, {"id": "stimuli", "name": "Чистые стимулы", "desc": "Убрать то, что выжигает дофамин.", "why": "«Триада биозомби»: бои, порно, негативные новости. «Чем больше смотришь новости, тем меньше зарабатываешь». Лента и порно делают обычную жизнь пресной.", "tiers": [{"n": 1, "mode": "once", "title": "Убрать ленты и новости с телефона, днём ч/б экран", "how": "Удалить или спрятать 3 самых затягивающих приложения.", "daily": "", "goal": "", "chapter": [{"check": "Телефон берёшь реже.", "practice": "Уведомления выключить, экран серый, первый экран телефона пустой.", "text": "Бои, порно, негативные новости. «Чем больше смотришь новости, тем меньше зарабатываешь». После «сникерсов» не чувствуешь вкус огурца с грядки.", "title": "Триада биозомби"}, {"practice": "Удали или спрячь 3 самых затягивающих приложения.", "text": "Лента, сериалы, чужие инстаграмы, порно — «корыто», чтобы не быть в реальности. Смысл не в том, чтобы мучиться воздержанием, а увидеть корыто и пнуть его.", "title": "Корыто"}]}, {"n": 2, "mode": "once", "title": "7 дней без триады: бои, порно, новости", "how": "Челлендж на неделю. Сорвался — не наказание, начать заново.", "daily": "", "goal": "", "chapter": [{"practice": "Отмечай каждый день в журнале.", "text": "Челлендж на 7 дней. Сорвался — не наказание: запиши, что спровоцировало, и начни заново.", "title": "Неделя без триады"}]}, {"n": 3, "mode": "once", "title": "30 дней без триады", "how": "Большое испытание. После него обычные удовольствия снова ярче.", "daily": "", "goal": "", "chapter": [{"practice": "Начинать только после удачной недели.", "text": "После месяца обычные удовольствия снова яркие: смотреть в окно, читать, слушать музыку.", "title": "30 дней"}]}], "fy": "Brawl Stars и ленты 3 часа в день — главный вор твоего времени на музыку."}, {"id": "sexenergy", "name": "Сексуальная энергия", "desc": "Не подавлять, а управлять: энергию — в тело и в дело. Дни воздержания не считаем подряд: счётчик сам наводит на мысль «сколько можно?» (Арсен).", "why": "Мозг считает «результат минус усилия». Порно и фантазии дают ему «победу» без усилий — и всё остальное блекнет: работа, спорт, люди. Когда этот кран закрыт, а энергия уходит в тело и дело, возвращаются воля, фокус, уверенность и умение доводить до конца.", "tiers": [{"n": 1, "mode": "days", "title": "Чистый день", "how": "Тянет — не запрещай себе, а вернись в реальность: глубокий вдох → посмотри на руки и потри их → «кто я, где я, что вокруг?» → встань и сделай 20 приседаний. Вечером отметь день.", "daily": "⚡ Чистый день: без порно и фантазий — отметить вечером", "goal": "21 чистый день", "days": 21, "chapter": [{"check": "Знаешь свои 2–3 момента, когда тянет.", "practice": "Заметь, когда тянет к лёгкому кайфу: обычно после неудачи, скуки или одиночества.", "text": "Мозг не отличает картинку от жизни. Порно и фантазии для него — секс, статус и победа сразу, без борьбы. Поэтому это сильнее любой другой радости, и обычная жизнь теряет вкус.", "title": "Победа без усилий"}, {"check": "Ритуал сработал хотя бы раз.", "practice": "Ритуал возврата: вдох → руки → «кто я, где я, что вокруг?» → 20 приседаний.", "text": "Иллюзия держится, пока ты выпал из реальности. Позвонили в дверь — и возбуждение пропало. Возврат в тело и в комнату ломает её за секунды. Это навык, как серфинг: тренируется, а не читается.", "title": "Разрушить иллюзию"}, {"practice": "Вместо «нельзя» — «это пиксели, мне это не нужно».", "text": "То, что себе запрещаешь, овладевает тобой. Цель не терпеть, а ясно видеть, что это пустое действие, и выбирать другое.", "title": "Запрет не работает"}]}, {"n": 2, "mode": "days", "title": "Энергию — в тело", "how": "Воздержание без движения не работает: энергия застаивается и тянет обратно. Раз в день — 30 приседаний, 3 минуты скакалки или бег. Сидишь долго — каждые 15–60 минут 10 лёгких сокращений Кегеля (несильно, для оттока крови). Свободное бельё.", "daily": "⚡ Энергию в тело: 30 приседаний или скакалка + Кегель при сидении", "goal": "21 день", "days": 21, "chapter": [{"practice": "30 приседаний или 3 минуты скакалки в день.", "text": "Гормоны разносятся жидкостями тела. Не двигаешься — энергия лежит мёртвым грузом. Приседания, ходьба, бег, скакалка, баня разгоняют кровь и лимфу.", "title": "Золото в вагонетках"}, {"practice": "Каждые 15–60 минут сидения — 10 лёгких сокращений.", "text": "От сидения и тесного белья кровь застаивается в тазу — и желание возвращается. Лёгкие сокращения Кегеля гонят свежую кровь; со временем нарастут сосуды и понадобится реже.", "title": "Застой в тазу"}, {"practice": "Одна песня вслух или танец в день.", "text": "Подавленные эмоции тело пытается догнать. Смейся, когда смешно, пой в машине или в душе, потанцуй утром — и лишнее напряжение уходит само.", "title": "Проявлять эмоции"}]}, {"n": 3, "mode": "days", "title": "14 дней норадреналина", "how": "14 дней без внешнего дофамина: лент, видео ради видео, порно, новостей, игр. Каждый вечер честно выписать, что в жизни не устраивает и злит, и один шаг против этого. Злость на своё положение — топливо, её не глушить кайфом.", "daily": "", "goal": "14 дней подряд", "days": 14, "chapter": [{"practice": "Недовольство не глушить, а записывать и превращать в шаг.", "text": "Дофамин — хотелки и лёгкий кайф, его можно получить лёжа. Норадреналин — только в действии: ринг, атака, вызов. Он сильнее дофамина и вытесняет лень. Его топливо — злость на своё положение, которую мы глушим лентой.", "title": "Два режима"}, {"practice": "Уведомления выключены, мысли — на бумагу.", "text": "Каждый лишний сигнал — уведомление, трек, новость — съедает ресурс внимания. Как тишина в бильярде перед ударом.", "title": "Тишина для фокуса"}], "steps": ["Убрать триггеры: уведомления, провокационные аккаунты, ленты", "Выписать на бумагу всё, что крутится в голове", "Каждое утро записать дату и «кто я, где я, что вокруг»", "Написать короткую биографию: какие годы — какие события", "Дни 1–7 без лент, видео, порно, новостей", "Каждый вечер: что меня не устраивает → один шаг", "Каждый день одно страшное дело: то, что стеснялся или боялся", "Дни 8–14 без внешнего дофамина", "Итог: что изменилось в фокусе, силе, общении"], "rank": "B"}], "fy": "Арсеновский челлендж, который ты сам выбрал."}, {"id": "reading", "name": "Чтение", "desc": "Загрузка знаний в голову.", "why": "Арсен читает минимум 4 часа в день уже 12 лет. Интуиция, по его словам, это объём загруженной информации, помноженный на ум.", "tiers": [{"n": 1, "mode": "days", "title": "20 минут в день", "how": "Книга или лекция по делу. Не лента.", "daily": "Чтение 20 минут", "goal": "", "days": 21, "chapter": [{"check": "Прочитанное хоть раз изменило завтрашний день.", "practice": "20 минут книги по делу или лекции. Твоя задача «10 страниц в день» — то же самое.", "text": "Арсен 12 лет читает минимум 4 часа в день. Интуиция — это объём загруженной информации, помноженный на ум. Начинаем с малого.", "title": "Зачем читать"}, {"practice": "После чтения — одна мысль, которую применишь.", "text": "«Прочитанная книга должна изменить твой завтрашний день — иначе в чём было чтение?»", "title": "Книга должна менять день"}]}, {"n": 2, "mode": "days", "title": "40 минут в день", "how": "Можно в наушниках на ходьбе.", "daily": "Чтение 40 минут", "goal": "", "days": 21}, {"n": 3, "mode": "days", "title": "1 час + короткий конспект главного", "how": "Записать одну мысль, которую применишь.", "daily": "Час чтения + одна мысль в журнал", "goal": "", "days": 21}], "fy": "Фантастика или детектив — с них и начни."}, {"id": "clarity", "name": "Ясность мысли", "desc": "Слышать, что говоришь, и понимать, зачем делаешь.", "why": "«99% тупости уходит, когда начинаешь слышать, что говоришь». Главный вопрос, который ставит на место любую глупость, — «Зачем?».", "tiers": [{"n": 1, "mode": "days", "title": "Одно точное определение в день", "how": "Взять слово, которое часто говоришь, и определить так, чтобы понял инопланетянин. Записать в журнал.", "daily": "Одно точное определение в день", "goal": "", "days": 21, "chapter": [{"check": "Можешь объяснить, что имеешь в виду.", "practice": "Одно слово в день, которое часто говоришь («успех», «лень»), — определить в журнале.", "text": "Определение — описание, по которому инопланетянин узнает вещь среди тысяч. «Если не можешь дать определение — лучше не говори».", "title": "Определение"}, {"practice": "Раз в день поймать одну свою пустую фразу.", "text": "«99% тупости уходит, когда начинаешь слышать, что говоришь, и соотносить с реальностью». Перед вопросом подумай 5–15 секунд.", "title": "Слышать, что говоришь"}]}, {"n": 2, "mode": "days", "title": "Раз в неделю разобрать одно своё «так надо»", "how": "Спросить «Зачем?» и «Почему?», пока не станет ясно.", "daily": "Разобрать одно своё «так надо»", "goal": "", "days": 21, "chapter": [{"practice": "Одно своё «так надо» разобрать вопросом «зачем?».", "text": "«Зачем» — это цель, «почему» — причина. Люди путают. «Зачем» ставит на место любую глупость.", "title": "Зачем, а не почему"}]}, {"n": 3, "mode": "once", "title": "Найти своё дело отсечением", "how": "Выписать, чем ты точно НЕ будешь заниматься, и отсекать, пока не останется своё.", "daily": "", "goal": ""}]}, {"id": "courage", "name": "Смелость", "desc": "Расширять границы маленькими шагами.", "why": "Каждый день маленькое «я бы так не смог». Ранг человека, по Арсену, растёт, когда он делает то, во что не верил. «Противоположность трусости — радость».", "tiers": [{"n": 1, "mode": "days", "title": "Одно маленькое «я бы так не смог» в день", "how": "Заговорить с незнакомым, лечь на газон, спросить скидку.", "daily": "Одно «я бы так не смог» в день", "goal": "", "days": 21, "chapter": [{"check": "К концу недели страшные мелочи стали обычными.", "practice": "Одно в день, самое маленькое.", "text": "Каждый день маленькое «я бы так не смог»: покачаться на качелях, сказать пару слов кассиру, лечь на газон. Лимарев называет это «зелёным действием».", "title": "Расширять границы"}, {"practice": "Сделал — отметь в журнале «зелёным».", "text": "Не смелость, а радость. Страх силён ровно настолько, насколько ты ему позволяешь.", "title": "Противоположность трусости"}]}, {"n": 2, "mode": "days", "title": "Раз в неделю сделать то, что пугает", "how": "Звонок, отказ, просьба, выступление.", "daily": "Раз в неделю сделать то, что пугает", "goal": "", "days": 21, "chapter": [{"practice": "Выбери в понедельник, сделай до воскресенья.", "text": "Звонок, отказ, просьба, выступление. Ранг растёт, когда делаешь то, во что не верил.", "title": "Раз в неделю"}]}, {"n": 3, "mode": "once", "title": "Вызов тому, кто сильнее", "how": "Спарринг, соревнование, разговор, которого боялся.", "daily": "", "goal": ""}], "fy": "Соцфобия лечится маленькими «я бы так не смог»."}, {"id": "tonic", "name": "Тоника", "desc": "Собраться целиком перед делом: чтобы тело и голова хотели одного.", "why": "Арсен называет тонику «самой важной темой, если хотите нормально жить». Без неё любое дело идёт в «ручном режиме» на силе воли — и ломается. У тебя: много начатых набросков, днём лень. Тоника — это про то, чтобы делать без надрыва.", "tiers": [{"n": 1, "mode": "days", "title": "Минута сборки", "how": "Перед главным делом дня — минута: выпрямиться, медленно подышать носом, представить готовый результат. Начинать, когда тело «согласно».", "daily": "Перед главным делом 1 минута собраться", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Главное дело начинается без внутренней войны.", "practice": "Перед делом спроси себя: тело «за» или я себя тащу?", "text": "Тоника — когда тело заранее подготовлено к тому, что ты собираешься делать. Без неё ты в «ручном режиме»: как первая поездка за рулём — 10 минут выматывают, как 6 часов.", "title": "Что такое тоника"}, {"check": "Меньше дел, брошенных на середине.", "practice": "Если тело против — не дави: уменьши шаг или сначала сними напряжение (прогулка, душ).", "text": "Арсен: подойти к девушке «на характере» без тоники — выходит клоунада. Так же с любым делом: против тоники оно разваливается.", "title": "Почему не получается «на силе воли»"}]}, {"n": 2, "mode": "days", "title": "Дисциплина в тонике", "how": "Нелюбимое дело совмещать с тем, что нравится: ходьба под кино, уборка под подкаст. Арсен так ходил по дорожке вечером, включив фильм.", "daily": "Неприятное дело — в паре с приятным", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Нелюбимое дело делается без отвращения.", "practice": "Для одного нелюбимого дела найди «пару»: музыку, место, награду.", "text": "Арсен: «Себя надо соблазнять, а не заставлять». Если в деле нет ничего приятного — добавь.", "title": "Соблазнять себя, а не заставлять"}]}, {"n": 3, "mode": "steps", "title": "Выпустить застрявшую эмоцию", "how": "Когда что-то давно выворачивает — не держать в себе.", "daily": "", "goal": "Сделать все шаги", "steps": ["Вспомнить, что или кто давно не отпускает", "Записать 15-минутное голосовое этому человеку со всем, что думаешь, — и удалить, не отправляя", "Или написать письмо, подписать и сжечь", "Записать одной строкой: что изменилось внутри"]}], "fy": "Тренировка под любимый трек — это и есть тоника."}, {"id": "words", "name": "Слова авторства", "desc": "Говорить о своей жизни как автор, а не как жертва.", "why": "Арсен: «Лексика взрослого: не „меня обманули“, а „я позволил себя обмануть“». Слова программируют, кто ты есть. Поймал себя на «я так устал» 50 раз в день — переводи в «хочу отдохнуть, хочу зарядиться». У тебя: «останусь таким же», «никогда не стану тем, кем хочу».", "tiers": [{"n": 1, "mode": "days", "title": "Поймать и заменить", "how": "За день поймать хотя бы одну фразу жертвы и сказать иначе: «я устал» → «хочу зарядиться», «меня обидели» → «я позволил», «не могу» → «пока не умею».", "daily": "Поймать «я устал» → «хочу зарядиться»", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Замечаешь фразы жертвы сам, без подсказки.", "practice": "Одна замена в день. Вслух или в голове.", "text": "Арсен: сказал «я так устал» — мозг выполняет. Заменил на «хочу зарядиться» — мозг ищет, как зарядиться.", "title": "Слова — это программа"}, {"check": "Жалоб с «но» стало меньше.", "practice": "Поймал «но» в жалобе — договори фразу без него.", "text": "Люди без авторства всегда говорят «но»: «был бы счастлив, но…». Пример Масвидаля: «проиграл честно, он сегодня лучше» — и никаких «но».", "title": "Без «но»"}]}, {"n": 2, "mode": "days", "title": "Говорю о том, что контролирую", "how": "Арсен: говорить о том, что не контролируешь (политика, чужие жизни), — признак слабости. Нормальный человек говорит о своём кошельке, здоровье, семье, деле.", "daily": "Говорю только о том, что контролирую", "goal": "21 день практики (не обязательно подряд)", "days": 21}, {"n": 3, "mode": "steps", "title": "Жалоба → шаг", "how": "Арсен сформулировал свою жалобу с позиции ответственности — и жалоба исчезла: понял, что может.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выписать одну главную жалобу на жизнь", "Переписать её от первого лица: «я позволил…», «я не сделал…»", "Найти одно действие, которое в твоей власти", "Сделать его в течение 24 часов"]}], "fy": "«Меня динамят» → «я звоню каждые 3 дня»."}, {"id": "rethink", "name": "Переосмысление", "desc": "Разбирать провалы как механик, а не судья.", "why": "Арсен: после провала не «он дегенерат», а найти у себя 20 ошибок — и исправить. Но без самобичевания: «осознал, понял, изменил программу, иду дальше». Ваагн: срыв — находка. Лимарев: провал — это разбор. В игре за честный разбор срыва дают опыт.", "tiers": [{"n": 1, "mode": "steps", "title": "20 своих ошибок", "how": "Взять один недавний провал (собес, ссора, сорванный день) и найти у себя 20 ошибок. Не чтобы ругать себя — чтобы починить.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выбрать один провал последнего месяца", "Выписать 20 своих ошибок в нём (мелкие тоже считаются)", "Отметить 3, которые можно исправить уже на этой неделе", "Исправить одну из них", "Создать задачу «Разбор срыва: …» — за неё +25 опыта"]}, {"n": 2, "mode": "steps", "title": "Недельный разбор", "how": "4 недели подряд, по пятницам: 10 минут на три вопроса.", "daily": "", "goal": "4 разбора", "steps": ["Неделя 1: что сработало? что нет? что я додумался НЕ делать?", "Неделя 2: то же + был ли это самый короткий путь к результату?", "Неделя 3: то же + где я добывал значимость словами, а не делом?", "Неделя 4: то же + что меняю в следующем месяце"]}, {"n": 3, "mode": "steps", "title": "День переосмысления", "how": "Арсен: после тяжёлого периода — день полного отдыха, инсайты письменно, практики по желанию.", "daily": "", "goal": "Один такой день", "steps": ["Выбрать день после тяжёлой недели", "Никаких дел и ленты — только отдых, прогулка, сон", "Вечером записать инсайты: что понял о себе", "Одно решение на следующую неделю"]}]}, {"id": "void", "name": "Создание пустоты", "desc": "Выбрасывать то, что держишь «на всякий случай».", "why": "Арсен называет это центральным навыком современности: всего в избытке, проблема — выбрать. Выжимать хоть что-то из проигрышной ситуации — тактическая победа и стратегическое поражение.", "tiers": [{"n": 1, "mode": "steps", "title": "10 вещей «на всякий случай»", "how": "Найти и убрать 10 вещей, которые держишь «на всякий случай»: вещи, приложения, подписки, чаты.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выписать 10 вещей, которые держишь «на всякий случай»", "Убрать первые 5", "Убрать оставшиеся 5", "Записать: что освободилось (место, время, голова)"]}, {"n": 2, "mode": "steps", "title": "Уйти из «не моего»", "how": "Арсен: «Проиграл до трусов — выйди в трусах». Выйти из одного, что точно не твоё: проект, группа, связь, привычка.", "daily": "", "goal": "Выйти", "steps": ["Назвать одно, что точно не твоё, но держишь", "Понять, что держит: страх, привычка, «жалко вложенного»", "Выйти — без попытки выжать пользу напоследок", "Через неделю записать, как стало"]}, {"n": 3, "mode": "steps", "title": "Не пора ли новой пустоте?", "how": "Мудрый создаёт пустоту заранее: раз в полгода отказаться от чего-то стабильного, если оно тормозит рост.", "daily": "", "goal": "Одно решение", "steps": ["Выписать, что даёт тебе больше всего стабильности", "Спросить: это растит меня или держит на месте?", "Если держит — решение и дата выхода"]}]}, {"id": "alive", "name": "Живость", "desc": "Возвращать вкус жизни новыми впечатлениями.", "why": "Арсен: «Сколько раз ты вставал без дел и шёл исследовать новую часть города — без карты, без плана?» Лимит скуки — это то, насколько любишь жизнь. Мало впечатлений за день — мало дофамина и хуже сон. Хочешь снова почувствовать — иди в новое, а не назад.", "tiers": [{"n": 1, "mode": "days", "title": "Новое впечатление дня", "how": "Каждый день что-то новое: другая дорога, новое блюдо, незнакомое место, новый человек, новая музыка.", "daily": "Одно новое впечатление за день", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Каждый день есть что вспомнить.", "practice": "Вечером в «Вечер 3 минуты» допиши одно новое за день.", "text": "Мало впечатлений — мало дофамина, хуже сон, тянет к ленте. Новое — дешёвый способ вернуть вкус дня.", "title": "Почему это важно"}, {"check": "Замечаешь свои желания.", "practice": "Раз в день сделай то, что захотелось, а не «как обычно».", "text": "Арсен: каждый день ловить себя — «что я хочу, как, куда, какой дорогой?». Сначала в мелочах.", "title": "Спонтанный импульс"}]}, {"n": 2, "mode": "steps", "title": "Без карты", "how": "4 выхода: встать и пойти туда, где ни разу не был, без карты и плана.", "daily": "", "goal": "4 выхода", "steps": ["Выход 1: новая часть города пешком", "Выход 2: новое место на природе", "Выход 3: место, куда давно хотел, но «не было повода»", "Выход 4: куда глаза глядят, 2 часа"]}, {"n": 3, "mode": "steps", "title": "Совсем новое — сегодня же", "how": "Арсен: «Я никогда не пробовал танцевать — сегодня же иду и танцую». Начать то, чего никогда не делал.", "daily": "", "goal": "Первое занятие", "steps": ["Выбрать то, чего никогда не делал (танцы, язык, скалодром, бокс)", "Найти ближайшую возможность", "Сходить на первое занятие в течение недели", "Записать ощущения"]}]}, {"id": "thoughtforms", "name": "Мыслеформы", "desc": "Писать установки от руки, чтобы перепрошить голову.", "why": "Арсен: мыслеформы — перепрошивка психики. Правила: без «не», конкретно, от первого лица, в одном направлении, с эмоцией. Базовые: мне можно, я могу, я беру, я делаю, я достоин. У тебя: «останусь таким же» — перепиши это в «я становлюсь тем, кем хочу».", "tiers": [{"n": 1, "mode": "days", "title": "5 базовых мыслеформ", "how": "Утром от руки: «Мне можно. Я могу. Я беру. Я делаю. Я достоин.» — и одна своя.", "daily": "5 мыслеформ от руки", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Хотя бы одна строка откликается.", "practice": "5 строк утром, рукой.", "text": "Без «не», конкретно, от первого лица, в одном направлении, с эмоциональным откликом. «Я не боюсь» — плохо; «я спокоен и уверен» — хорошо.", "title": "Правила мыслеформ"}, {"practice": "Иногда пиши после «Холода» или «Прогулки».", "text": "Сильнее всего писать на пике состояния: после холода, тренировки, прогулки.", "title": "На пике"}]}, {"n": 2, "mode": "days", "title": "По секторам жизни", "how": "5 секторов (деньги, тело, люди, образ, ум) — по 2–3 строки на каждый.", "daily": "Мыслеформы по 5 секторам жизни", "goal": "21 день практики (не обязательно подряд)", "days": 21}, {"n": 3, "mode": "days", "title": "Час мыслеформ", "how": "Арсен писал минимум час в день, лист на сектор.", "daily": "Мыслеформы 20–60 минут", "goal": "21 день практики (не обязательно подряд)", "days": 21}], "fy": "Вместо «останусь таким же» — «я становлюсь тем, кем хочу»."}, {"id": "will", "name": "Воля к жизни", "desc": "Базовый дискомфорт + лучшее удовольствие + вера, что путь есть.", "why": "Арсен: воля к жизни = базовый дискомфорт + уровень удовольствия + дуга интуиции (веришь, что путь отсюда туда есть). Условия вместо силы воли: «выкинь торт в окно». Удовольствие — меньше, но только лучшее.", "tiers": [{"n": 1, "mode": "steps", "title": "Базовый дискомфорт", "how": "Убрать один комфорт, который расслабляет, и создать условия вместо силы воли.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выписать 3 комфорта, которые тебя расслабляют (сладкое дома, мягкий диван днём, телефон у кровати)", "Убрать один физически — «выкинь торт в окно»", "Прожить так неделю", "Записать, что изменилось"]}, {"n": 2, "mode": "steps", "title": "Уровень удовольствия", "how": "Меньше удовольствий, но только лучшие. Жизнь должна радовать, а не удовлетворять.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выписать свои частые удовольствия", "Оставить 3 самых лучших, остальные убрать на 2 недели", "Одно удовольствие сделать «по-королевски»"]}, {"n": 3, "mode": "steps", "title": "100 миллионов и 10 000 лет", "how": "Представить, что у тебя 100 млн долларов и 10 000 лет жизни. Чем бы ты занимался? Это и есть то, что зажигает.", "daily": "", "goal": "Найти своё", "steps": ["Написать от руки: что бы делал со 100 млн и 10 000 лет", "Отметить, что повторяется и зажигает", "Одно действие к этому на этой неделе"]}]}, {"id": "antihelp", "name": "Против беспомощности", "desc": "Вытаскивать себя из ямы маленькими победами.", "why": "Арсен, «Лекарство от беспомощности»: дневник побед, антистрессовый дневник (страхи, которые не сбылись) и каждый день делать то, что кажется «не смог бы». У тебя: тоска почти каждый день. Если так больше двух недель — сходи к психологу или врачу.", "tiers": [{"n": 1, "mode": "steps", "title": "Антистрессовый дневник", "how": "2 недели записывать страхи и тревоги, а потом отмечать, какие не сбылись.", "daily": "", "goal": "2 недели", "steps": ["Завести страницу «Страхи»", "Неделя 1: записывать каждый страх одной строкой с датой", "Неделя 2: продолжать и отмечать, какие не сбылись", "Посчитать: сколько из записанного реально случилось"]}, {"n": 2, "mode": "days", "title": "Подсвечивание побед", "how": "На каждом результате — 3 секунды осознать: «видел? работает!». Вечером одну победу записать.", "daily": "Одна победа в день: 3 секунды «видел? работает!»", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Вечером есть что записать в победы.", "practice": "Сделал дело — пауза 3 секунды: «видел? работает!»", "text": "Арсен: мозг не замечает побед сам. Их надо подсвечивать — 3 секунды внимания на результат.", "title": "Подсвечивание"}]}, {"n": 3, "mode": "days", "title": "Список «точно сделаю» в плохой день", "how": "В яме — 3–7 пунктов, которые точно сделаешь, даже «проснуться, почистить зубы».", "daily": "", "goal": "7 плохих дней", "days": 7, "steps": ["Составить список-минимум на плохой день (у тебя есть задача «что делать, когда нет сил»)", "В следующий плохой день выполнить список", "Так 7 плохих дней — отмечать галочкой"]}], "fy": "Если тоска давит — этот навык первый."}, {"id": "incarnation", "name": "Инкарнация", "desc": "Вселять образ героя под ситуацию.", "why": "Арсен: под ситуацию «вселять» образ — Мрак, Гатс, Тайсон — и тренировать на малом. Зеркальные нейроны: фильмы, книги и музыка героического типа меняют самоощущение.", "tiers": [{"n": 1, "mode": "steps", "title": "Выбрать героя", "how": "Найти 1–2 героев, чьё состояние тебе нужно, и понять, как они двигаются и говорят.", "daily": "", "goal": "Сделать все шаги", "steps": ["Выбрать героя под ситуацию (собеседование, спортзал, разговор)", "Посмотреть 2–3 сцены с ним и заметить позу, голос, взгляд", "Попробовать «надеть» его на 5 минут в простой ситуации"]}, {"n": 2, "mode": "days", "title": "Инкарнация на малом", "how": "Одно дело в день сделать «как герой»: зайти в магазин, позвонить, тренировка.", "daily": "Инкарнация героя на одном деле", "goal": "21 день практики (не обязательно подряд)", "days": 21}, {"n": 3, "mode": "steps", "title": "Инкарнация в стрессе", "how": "Использовать героя в реально трудной ситуации.", "daily": "", "goal": "Один раз", "steps": ["Выбрать трудную ситуацию недели", "Перед ней 1 минута — «надеть» героя", "После — записать, что получилось"]}]}, {"id": "learn", "name": "Учиться", "desc": "Учиться так, чтобы знание становилось делом.", "why": "Арсен: в эпоху избытка информации выигрывает не тот, кто больше знает, а кто внедряет. Для музыки — прямой путь: учиться быстро и показывать результат.", "tiers": [{"n": 1, "mode": "steps", "title": "Ритуал ученика", "how": "Перед уроком встать, сказать себе «я ничего не знаю», записать один вопрос. Учиться стоя.", "daily": "", "goal": "Сделать все шаги", "steps": ["3 урока или эфира: перед началом встать и записать 1 вопрос", "Учиться стоя", "После урока — 3 мысли своими словами и одно дело на завтра"]}, {"n": 2, "mode": "steps", "title": "Выбрать мастера", "how": "Выбрать мастера по музыке по правилу «как живёт он и его ученики».", "daily": "", "goal": "Сделать все шаги", "steps": ["Выписать 3 кандидатов в учителя по битам и сведению", "Про каждого: как живёт он и его ученики, есть ли результаты", "Выбрать одного и пройти у него один урок или разбор"]}, {"n": 3, "mode": "steps", "title": "Своё мини-сообщество", "how": "Собрать 2–3 человек, которые учатся тому же, и разбирать друг друга.", "daily": "", "goal": "Сделать все шаги", "steps": ["Найти 2–3 человек, которые учатся тому же", "Договориться о еженедельном разборе", "Провести 3 встречи"]}], "fy": "Учись у тех, кто уже делает музыку, которую ты любишь."}, {"id": "selfrel", "name": "Отношение к себе", "desc": "Не ругать себя, а вести — как отец ведёт сына.", "why": "Кто годами ругает себя, тот бьёт брошенного ребёнка, который кое-как вырос. Сила спокойна: разбор ошибки без самобичевания, честная оценка себя и поиск того, что тебя на самом деле наполняет.", "tiers": [{"n": 1, "mode": "days", "title": "Как с сыном", "how": "Неделю каждый вечер: одна фраза поддержки себе — такая, какую сказал бы своему сыну, — и одна победа дня без «подумаешь». Поймал себя на «я дебил» — переформулируй как отец.", "daily": "", "goal": "7 дней подряд", "days": 7, "chapter": [{"practice": "Одна фраза вечером.", "text": "Представь, что всё, что ты знаешь о себе, — это твой сын. Что ты ему скажешь, если он называет себя чмом? Это и скажи себе.", "title": "Отец самому себе"}, {"practice": "«Понял — меняю — иду дальше».", "text": "Как механик: нашёл поломку — починил — ищи следующую. Ошибка должна задеть, чтобы не повторить, но без казни себя.", "title": "Переосмысление, а не самобичевание"}], "steps": ["День 1: фраза-поддержка + победа дня", "День 2: то же", "День 3: поймать одно «я дебил» и переписать как отец", "День 4: фраза-поддержка + победа", "День 5: разбор одной ошибки: что понял — что меняю — пошёл дальше", "День 6: фраза-поддержка + победа", "День 7: что изменилось в настроении"]}, {"n": 2, "mode": "days", "title": "Дневник пиков радости", "how": "14 дней по вечерам: одна строка «пик дня — что, во сколько, сила 1–10». Через 2 недели — видно, что на самом деле тебя наполняет.", "daily": "", "goal": "14 дней", "days": 14, "chapter": [{"practice": "Записывай честно, даже если пик — мелочь.", "text": "«У меня всё есть для счастья, а счастья нет» — значит, маркеры чужие. Свои находятся по пикам радости.", "title": "Навязанные маркеры"}, {"practice": "Отметь, где пик связан с делом.", "text": "Радость приходит от дела, которое получается, а получается то, к чему есть задатки.", "title": "Удовольствие — от того, что получается"}], "steps": ["Дни 1–7: каждый вечер пик дня", "Дни 8–14: каждый вечер пик дня", "Выписать 5 самых сильных пиков", "Найти, что у них общего", "Назвать свой ключевой ресурс: деньги, признание, отклик людей, победа"]}, {"n": 3, "mode": "steps", "title": "Карта одобрения и ключевой ресурс", "how": "Понять, какие программы тобой управляют, и связать свой ключевой ресурс с работой.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"practice": "Вспоминай конкретные сцены.", "text": "До 7 лет закладываются бессознательные стремления, до 14 — осознанные. Пока их не увидел — не управляешь ими.", "title": "Детское одобрение"}], "steps": ["За что меня хвалили до 7 лет — 5 пунктов", "За что хвалили до 14 лет — 5 пунктов", "Какие мои нынешние цели держатся на этом", "Мой ключевой ресурс по дневнику радости", "Как сделать музыку источником этого ресурса", "Что прёт — делаю сам, что не прёт — кому отдать"], "rank": "B"}], "fy": "Ты говоришь о себе жёстко. Говори как с братом."}], "rows": [["journal", "morning", "learn"], ["words", "stimuli", "calm", "reading"], ["rethink", "sexenergy", "selfrel", "clarity"], ["antihelp", "courage", "tonic", "void"], ["will", "thoughtforms", "alive"], ["incarnation"]], "parents": {"alive": ["void", "courage"], "antihelp": ["rethink", "selfrel"], "calm": ["morning"], "clarity": ["reading"], "courage": ["sexenergy"], "incarnation": ["will", "thoughtforms"], "reading": ["learn"], "rethink": ["words"], "selfrel": ["journal", "calm"], "sexenergy": ["stimuli"], "stimuli": ["morning"], "thoughtforms": ["tonic"], "tonic": ["calm"], "void": ["clarity"], "will": ["antihelp"], "words": ["journal"]}}, {"key": "telo", "p": "body", "name": "Тело", "short": "здоровье и боеспособность", "why": "Тело улучшает все остальные пути: больше крови к мозгу — лучше думаешь, лучше выглядишь — сильнее впечатление. Арсен: «главный фактор всего — сон», а ходьба «лечит практически всё».", "skills": [{"id": "walk", "name": "Ходьба", "desc": "Главный протокол Арсена: ходьба по прямой, из точки А в точку Б.", "why": "Снимает «разгон» и туман в голове, запускает дофамин и BDNF (вещество роста нейронов), выравнивает осанку. На фоне ежедневной ходьбы закрепляется любая новая привычка — это его метод «переписать привычку».", "tiers": [{"n": 1, "mode": "days", "title": "База: 30 минут в день", "how": "Прогулка 30 минут любым темпом", "daily": "Прогулка 30 минут любым темпом", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Прогулка стала обычной частью дня.", "practice": "Иди куда-то, а не кругами: из точки А в точку Б. Круги раскачивают, как качели.", "text": "Бег даёт адреналин: тело «убегает от невидимого хищника» и истощается, а при перекосах в теле бег их усиливает. Ходьба восстанавливает биомеханику. Велосипед такого эффекта не даёт.", "title": "Почему ходьба, а не бег"}, {"check": "К обеду голова яснее, чем обычно.", "practice": "Если получается — выходи до завтрака, пусть на те же 30 минут.", "text": "Утренняя ходьба — «бафф на весь день». Натощак ещё лучше.", "title": "Лучше утром"}, {"check": "После ходьбы ноги не гудят.", "practice": "До и после прогулки 2–3 минуты раскатай стопу жёстким массажным мячом (не теннисным): свод и подушечки пальцев.", "text": "Тонус всего тела равен тонусу самой уставшей мышцы, а стопы устают первыми.", "title": "Стопы"}]}, {"n": 2, "mode": "days", "title": "Протокол 45 + 15", "how": "45 минут быстрым шагом + 15 минут отдыха", "daily": "45 минут быстрым шагом + 15 минут отдыха", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "После прогулки хочется сесть и делать.", "practice": "45 минут быстрым шагом, 15 отдыха. Остановки на 1–2 минуты — на растяжку.", "text": "С 45–60 минут ходьбы растут дофамин и BDNF: появляется желание что-то делать, легче начать дела.", "title": "Дофамин с 45-й минуты"}, {"check": "Воспоминание стало легче.", "practice": "Раз за прогулку вспомни одно поражение и просто иди с ним, не разбирая.", "text": "Во время ходьбы можно спокойно прокручивать неприятные и унизительные моменты — шаг их «перемалывает».", "title": "Вышагивать поражения"}, {"practice": "Когда эта ступень освоена, бери новый навык — внедряй его на фоне ходьбы.", "text": "Метод Арсена: 2–3 недели держись на ежедневной ходьбе, а уже на этом фоне 2–3 недели делай новую привычку на силе воли. Так она закрепляется очень жёстко.", "title": "Переписать привычку"}]}, {"n": 3, "mode": "days", "title": "Долгая ходьба: 1,5–3 часа", "how": "От 1,5 до 3 часов по прямой", "daily": "От 1,5 до 3 часов по прямой", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Шорты «перестают впиваться».", "practice": "Раз в неделю длинная прогулка от 2 часов, в остальные дни — сколько получается, от 1 часа.", "text": "Первый час телу почти ничего не даёт. Со второго подтягиваются живот, ягодицы, грудь, включается осанка.", "title": "Эффект со второго часа"}, {"practice": "Совмещай ходьбу с делом: лекции, звонки, продумывание задач.", "text": "Утром и вечером по 3 часа — «способ изменить судьбу»: многие перед рывком работали курьерами. После ходьбы садишься с ручкой и работаешь.", "title": "Изменить судьбу"}, {"practice": "Язык в нёбо, затылок назад, шаг с пятки.", "text": "Ходьба 3 часа с правильной осанкой «лечит практически всё»: встряхивает всё тело — «вертикальную лужу».", "title": "Осанка на ходу"}]}], "fy": "Минус вес и плюс энергия начинаются с ног."}, {"id": "sleep", "name": "Сон", "desc": "Режим и качество сна. Главная ежедневка с первого дня.", "why": "Все трое сходятся: сон выше всего. Арсен: сон — главный фактор, недосып рушит самоконтроль сильнее всего остального. Ваагн: пока сон сбит, остальные цели на паузе («сезон сна»). Лимарев: 7,5–9 часов и отбой в одно время.", "tiers": [{"n": 1, "mode": "days", "title": "Отбой и телефон не у кровати", "how": "В 23:30 телефон на зарядку в другом месте, не у кровати. В 00:00 — в кровать, свет выключен. Утром вставать сразу.", "daily": "Сон: отбой до 00:00, телефон в 23:30 не у кровати", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Отбой до 23:00 минимум 5 ночей из 7.", "practice": "Первые две недели главная победа дня — лечь вовремя.", "text": "Ваагн: пока сон сбит, остальное не растёт — сначала «сезон сна». Лимарев: мозг даёт силы, только когда восстановлен. Арсен: недосып рушит самоконтроль сильнее всего.", "title": "Почему сон первый"}, {"check": "В кровати нет телефона.", "practice": "В 23:30 телефон на зарядку в другой угол или комнату. Будильник — там же: придётся встать, чтобы выключить.", "text": "Ленты, Brawl Stars и порно вечером забирают сон. Лента перед сном разгоняет мозг, и засыпаешь позже, чем ложишься.", "title": "Телефон — главный вор сна"}, {"check": "Засыпаешь за 20 минут.", "practice": "Днём не ложиться. Устал — прогулка 10 минут или душ.", "text": "", "title": "Дневной сон сбивает ночной"}, {"check": "Знаешь свою честную оценку сна за неделю.", "practice": "Каждое утро отмечай: бодро, средне или разбито.", "text": "Упал — не помнишь, как заснул — яркие сны без пробуждений — проснулся, как после двух чашек кофе. Чем дольше встаёшь с кровати, тем хуже был сон. Разбитость по утрам — не норма, это чинится.", "title": "Какой сон — норма"}, {"practice": "Свет в глаза, 3 благодарности и одно приятное дело до телефона.", "text": "Первые 15–20 минут задают настрой на весь день. Поблагодари за то, что есть, окинь день мыслью «со всем справлюсь, а если пойдёт не так — сориентируюсь». Первым делом — что-то приятное.", "title": "Утро задаёт день"}]}, {"n": 2, "mode": "days", "title": "Полная темнота и ч/б экран за час", "how": "Вечером тёплый приглушённый свет и фильтр синего (или ч/б экран) за час до сна. Полная темнота: маска или шторы. Беруши при шуме, комнату проветрить. Утром — 10 минут дневного света.", "daily": "Экран в ч/б за час до сна + полная темнота", "goal": "21 день практики", "days": 21, "chapter": [{"practice": "После 21:00 тёплый свет и фильтр синего.", "text": "Холодный яркий свет, экраны и фары говорят глазам «день ещё идёт» — мелатонин не вырабатывается. Вечером — тёплый приглушённый свет, свечи, фильтр синего на экранах.", "title": "Свет решает"}, {"practice": "Утром 10 минут дневного света, днём выходить на улицу.", "text": "Мелатонин делается из серотонина, накопленного за день. Серотонин растёт от солнечного света на сетчатку и кожу. Не было света днём — не из чего сделать сон.", "title": "Серотонин днём — мелатонин ночью"}, {"practice": "Проветрить перед сном, беруши при шуме.", "text": "В душной комнате засыпаешь легко, но сон пустой. Нужен свежий воздух. Шум и чужие звуки мозг считает опасностью: беруши, один и тот же спокойный фон перед сном.", "title": "Воздух и тишина"}]}, {"n": 3, "mode": "days", "title": "Ритуал сна", "how": "Дела закончены за 2 часа до сна, еда — за 3 часа. За час — горячий душ, потом остыть. Тревожные мысли — на бумагу. Спальня проветрена и прохладная к утру. Медленное дыхание носом с длинным выдохом.", "daily": "Ритуал сна", "goal": "21 день практики", "days": 21, "chapter": [{"practice": "Горячий душ за час до сна.", "text": "Засыпание запускает падение температуры тела. Горячий душ, ванна или тренировка с перегревом за час до сна, потом остывание — и приходит сонливость.", "title": "Уснуть — значит остыть"}, {"practice": "Последняя еда не позже чем за 3 часа до сна.", "text": "Низкий сахар вечером усыпляет, а к утру будит: кортизол поднимает на поиск еды. Ложись без еды в животе — ужин за 3 часа до сна.", "title": "Спать без еды"}, {"practice": "Чем раньше подвигался, тем раньше захочешь спать.", "text": "За день тело должно потратить свой адреналин в движении — только тогда вечером включается торможение. Шум и сидячий день оставляют адреналин в крови до ночи.", "title": "Адреналин тратить днём"}, {"practice": "Форточка на ночь, одеяло потеплее.", "text": "К утру в комнате должно стать прохладно — тело просыпается само, и бодрость не пропадает, в отличие от прыжка под будильник.", "title": "Прохлада будит лучше будильника"}, {"practice": "Чинить сон режимом, а не таблетками.", "text": "Дозы в таблетках огромные: тело перестаёт делать свой мелатонин, держится высокий пролактин, нужна всё большая доза. Любые добавки для сна — только через врача.", "title": "Мелатонин в таблетках — нет"}]}], "fy": "Ты ложишься в 12 — держи это и сделай сон глубже."}, {"id": "cold", "name": "Холод", "desc": "Холодная вода как тренировка нервной системы.", "why": "Поднимает тонус и ГАМК (спокойствие). Правила Арсена: коротко, в удовольствие, контролируемо, выходить на пике, сразу в тепло.", "tiers": [{"n": 1, "mode": "days", "title": "10 секунд холодной воды в конце душа", "how": "Сначала ладони и стопы, потом тело.", "daily": "10 секунд холодной воды в конце душа", "goal": "", "days": 21, "chapter": [{"check": "После душа бодрость, а не озноб.", "practice": "В конце душа: сначала ладони и стопы, потом всё тело, 10 секунд.", "text": "Арсен: 5–10 секунд холодной воды — сильнейший подъём норадреналина, «кикстартер» начала дел. Лёд мешками не нужен.", "title": "Зачем холод"}, {"practice": "Не терпеть до дрожи. 10 секунд — и хватит.", "text": "Коротко, в удовольствие, контролируемо. Выходить на пике, сразу в тепло. Чем экстремальнее практика, тем меньше шанс, что она закрепится.", "title": "Правила"}]}, {"n": 2, "mode": "days", "title": "Умывание холодной водой + стопы в холодную воду", "how": "Холодные стопы по Арсену снимают отёк носоглотки.", "daily": "Холодное умывание + стопы в холодную воду", "goal": "", "days": 21, "chapter": [{"practice": "Тазик холодной воды, стопы 1 минута, потом растереть полотенцем.", "text": "Стопы связаны с носоглоткой: 1–2 минуты стопы в холодной воде снимают отёк носа (Арсен).", "title": "Стопы и нос"}]}, {"n": 3, "mode": "days", "title": "Холодная ванна 1–2 минуты", "how": "По плану, без геройства, не дольше 10 минут никогда.", "daily": "Холодная ванна 1–2 минуты", "goal": "", "days": 21, "chapter": [{"practice": "Заранее решить время, после — сразу в тепло.", "text": "Новичку 1–2 минуты, никогда не дольше 10. Время — по плану, заранее.", "title": "Ванна без геройства"}]}]}, {"id": "food", "name": "Питание", "desc": "Еда как топливо, а не как успокоительное.", "why": "«Лучше голодай, чем что попало ешь». Тяга к еде часто не голод, а стресс и нехватка лептина: мозгу кажется, что еды мало.", "tiers": [{"n": 1, "mode": "days", "title": "«Лептиновый салат» первым блюдом на ужин", "how": "Много овощей, масло, лимон или уксус, немного орехов. Потом ешь что хочешь — съешь меньше.", "daily": "«Лептиновый салат» первым блюдом на ужин", "goal": "", "days": 21, "chapter": [{"check": "Вечером меньше тянет на сладкое.", "practice": "Ужин начинать с салата: много овощей, ложка масла, лимон или уксус, немного орехов. Потом ешь что хочешь — съешь меньше.", "text": "Лептин низкий — мозгу кажется, что еды мало («ты в Бухенвальде»), и он заставляет есть больше.", "title": "Почему тянет переедать"}, {"practice": "После обеда — 10 минут пройтись.", "text": "Арсен: после еды 10 минут ходьбы или 15–30 приседаний — сахар в крови не скачет.", "title": "Сахар после еды"}]}, {"n": 2, "mode": "days", "title": "Дома всегда нормальная еда, без фастфуда 5 дней в неделю", "how": "Когда дома много еды, мозг перестаёт паниковать.", "daily": "Дома нормальная еда, без фастфуда", "goal": "", "days": 21, "chapter": [{"practice": "В субботу закупка по списку (твоя задача в 🍎 Питание).", "text": "Когда дома всегда много нормальной еды, мозг перестаёт паниковать и хватать фастфуд.", "title": "Забить дом едой"}]}, {"n": 3, "mode": "days", "title": "«Мужская еда» каждый день", "how": "Семечки тыквы, грецкие орехи, капуста, брокколи, чеснок, имбирь, яйца, мясо.", "daily": "«Мужская еда» каждый день", "goal": "", "days": 21, "chapter": [{"practice": "Одна «мужская» еда в каждый приём.", "text": "Семена тыквы, грецкий орех, капуста и брокколи, сельдерей, имбирь, чеснок, шпинат, авокадо, яйца, мясо. «Лучше голодай, чем что попало ешь».", "title": "Мужская еда"}]}], "fy": "Сладкое от скуки и пиво — главное, что убрать."}, {"id": "checkup", "name": "Анализы", "desc": "Цифры о своём теле.", "why": "Арсен всё строит от анализов. «Как поднять самооценку? — сдать анализ на тестостерон». Без цифр тело качается вслепую.", "tiers": [{"n": 1, "mode": "once", "title": "Сдать базовые анализы", "how": "ТТГ, пролактин, эстрадиол, тестостерон общий и свободный, ГСПГ, витамин D, B12, печень (АЛТ, АСТ).", "daily": "", "goal": "", "chapter": [{"practice": "Сдавать утром натощак, в одно время и в одних условиях.", "text": "Арсен: «Как поднять самооценку? — сдать анализ на тестостерон». Без цифр тело качается вслепую.", "title": "Зачем анализы"}, {"practice": "Список отдать в лабораторию целиком. Это твоя задача «после 2-й зарплаты» в 🩺 Здоровье.", "text": "Тестостерон общий и свободный, ГСПГ, пролактин, эстрадиол, кортизол, ТТГ, витамин D, B12, печень (АЛТ, АСТ). Базовый набор — около 10 тыс. ₽.", "title": "Что сдать"}, {"practice": "Запланируй сдачу на утро после 3 спокойных дней.", "text": "Чтобы увидеть свой обычный фон: 3 дня нормально спать, 3 дня без эякуляции, пить воду, есть как обычно. Утром перед сдачей — без долгой ходьбы, без эмоций, даже без видео. Для точности — повторить 2–3 утра подряд. Бессонная ночь поднимает кортизол в разы. Результаты смотрит эндокринолог.", "title": "Как сдавать правильно"}]}, {"n": 2, "mode": "once", "title": "Разобрать результаты и составить план", "how": "С врачом или вместе с Claude: что поднять, что опустить.", "daily": "", "goal": "", "chapter": [{"practice": "Разобрать с врачом или с Claude: что поднять, что опустить.", "text": "Ориентиры Арсена: ТТГ до 1,5; пролактин у нижней границы; эстрадиол ниже середины; ГСПГ низкий; витамин D от 80. Лекарства — только после врача.", "title": "Разбор"}]}, {"n": 3, "mode": "once", "title": "Пересдать через 2–3 месяца и сравнить", "how": "Одно время дня, одни условия.", "daily": "", "goal": ""}]}, {"id": "sex", "name": "Секс", "desc": "Сексуальная сила тела и умение: от таза и сосудов до самого секса.", "why": "Арсен: высшая точка удовольствия в жизни задаёт работоспособность и целеустремлённость — чем ярче пик, тем яснее, ради чего всё. Высшее удовольствие — сексуальное. Если секс блёклый, человек мало чего хочет и становится пассивным.", "tiers": [{"n": 1, "mode": "days", "title": "Таз и сосуды", "how": "Кегель 100 лёгких сокращений + 5 минут стойки у стены", "daily": "Кегель 100 + 5 минут стойки у стены", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Понимаешь, что именно у тебя слабее, и не путаешь одно с другим.", "practice": "Запомни разницу: желание — от гормонов и состояния, твёрдость — от крови и таза.", "text": "Возбуждение и эрекция — разные вещи. Возбуждение — «как будто якорем зацепило в солнечном сплетении», его даёт тестостерон: чем его больше, тем сексуальнее кажутся женщины и тем меньше нужны порно и прочие стимуляторы. Эрекция — это сосуды и оксид азота. Качаем обе.", "title": "Две разные системы"}, {"check": "Делаешь сотню без усилия, между делом.", "practice": "Сжимай мышцу, которой останавливаешь мочеиспускание, легко и в ритме. Начни со 100 в день, потом прибавляй. Присед у стены — когда есть время.", "text": "Тазовое дно работает как сердце: ему нужны не редкие мощные сокращения, а частая лёгкая прокачка крови. «Лучше 500 поверхностных, чем 50 мощных». Вторая версия Арсена: сесть в глубокий присед спиной к стене — кровь наливается в таз, и сокращения идут с сопротивлением. Он сидит так до 20 минут, заодно в телефоне.", "title": "Кегель — поверхностно и много"}, {"check": "Стоишь и сидишь ровно без напоминаний.", "practice": "Каждый день 5–10 минут стой у стены: пятки, поясница (не ягодицы), лопатки и затылок касаются стены. Сиди на седалищных буграх, а не на промежности. Под задние ножки стула подложи высоту 2,5 книги. Спи на твёрдом.", "text": "У большинства из-за многолетнего сидения поясница прогнута, живот вывален, органы таза давят вперёд. Арсен: «таз всему голова, всё начинается с таза». Подтяни лобок, сведи ягодицы, как в планке, — это возвращает нормальную механику.", "title": "Таз всему голова"}, {"check": "Своё желание воспринимаешь спокойно, как норму.", "practice": "Свободное бельё или без него на ночь. Холодное подмывание по утрам, горячая ванна при застое. Раз в пару дней 15–20 минут раскатывай промежностью мягкую подушку-валик.", "text": "По Арсену, стыд за своё желание — корень многих бед: ложный подростковый вывод «мужская сексуальность постыдна» зажимает тазовое дно и бьёт по гормонам. Стыдиться хотеть секса — никогда. И всё, что давит, мешает: тесные трусы, узкие джинсы, ремни.", "title": "Без стыда и без тесноты"}], "watch": [{"min": 55, "title": "Гайд по сексу", "where": "база «Тестостерон релиз» в Телеграме"}, {"note": "видео без расшифровки, посмотри целиком", "title": "Кегель II", "where": "база «Тестостерон релиз» в Телеграме"}]}, {"n": 2, "mode": "days", "title": "Кровь и гормоны", "how": "Час движения в день и без тяжёлой еды вечером", "daily": "Час движения в день и без тяжёлой еды вечером", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "После нагрузки чувствуешь прилив, а не усталость.", "practice": "Час движения каждый день. Если ходишь в зал — подходы по 15–18 повторов.", "text": "Лучшее для эрекции — долгая циклическая нагрузка: ходьба, велосипед, бег, эллипс. Кровь идёт по тазу, растут новые сосуды, кровь становится текучее. «Час-два прогулки в день на самом деле хватает». Второе — железо на памп: 15–18 повторов, не на максимальный вес, — это больше оксида азота.", "title": "Движение качает сосуды"}, {"check": "Утренняя эрекция появляется чаще.", "practice": "Клетчатка каждый день, сладкое вниз, вечером ничего тяжёлого. Воды — много.", "text": "Лишний вес забирает кровь, сахар делает её густой, забитый кишечник давит на простату. Арсен как-то съел 6 бигмаков и 4 литра колы — «ощущение, как будто ты евнух». Кровь должна быть жидкой: пенис — губка, густая кровь её не наполняет.", "title": "Вес, сахар, кишечник"}, {"check": "Больше драйва и настроения в солнечные недели.", "practice": "В солнечные дни 15–30 минут на солнце в эти часы.", "text": "Арсен: загар — это не косметика, а гормоны, «лекарство для души» и прямой рост сексуального драйва. Загорать только утром (8–11) и ближе к вечеру (16–19), кожу мазать кокосовым маслом, не обгорать.", "title": "Загар — гормональная процедура"}, {"check": "Желание сильное и направлено на живых женщин, а не на экран.", "practice": "Держи практику из трека «Женщины»: без порно и мастурбации.", "text": "«То, что вы готовы творить в постели после трёх недель воздержания… с ума сойти». После 2,5 месяцев у Арсена заряда хватило на полгода. «После дрочки начинаются все проблемы».", "title": "Воздержание заряжает"}]}, {"n": 3, "mode": "steps", "title": "Умение", "how": "Первая близость — по взаимному желанию", "daily": "Первая близость — по взаимному желанию", "goal": "сделать один раз", "chapter": [{"check": "Идёшь в это спокойно, как в новую тренировку.", "practice": "Перед первой близостью перечитай этот свиток. Презервативы — с собой всегда.", "text": "Арсен: «Сексом уметь заниматься надо: позы, углы, подготовка, состояние, фрикции — целая наука, трактаты можно писать». Никто не рождается умеющим, поэтому неопытность — нормальная стартовая точка.", "title": "Этому учатся"}, {"check": "Вам обоим хорошо, и она хочет повторить.", "practice": "Смотри на её реакцию: хорошо ей — продолжай, нет — остановись и спроси.", "text": "По Арсену, женщина получает максимум, когда мужчина, который ей по-настоящему нравится, хочет её и берёт с удовольствием для себя. Не «обслуживать» и не сдавать экзамен, а хотеть — и чтобы она этого хотела тоже.", "title": "Что ей на самом деле нравится"}, {"check": "После близости бодрость, а не опустошение.", "practice": "Не жди идеального момента, если оба хотят.", "text": "Лучшее — сразу на волне желания. Долгая прелюдия «по плану» часто гасит желание: «запускаю доту — и ставят паузу на 15 минут». После секса — не проваливаться в сонную апатию, а падать на бодрую волну: встать, двигаться, радоваться.", "title": "На волне желания"}, {"check": "Управляешь темпом, а не он тобой.", "practice": "Поищи угол, при котором ей очень хорошо, а тебя не так сильно разгоняет.", "text": "Двигайся из положения планки: ягодицы сведены, без прогиба в пояснице. Чувствуешь, что подпирает, — смени угол или сделай паузу, пусть её удовольствие продолжается, а ты передохнёшь. Доводить себя рукой, даже после секса, — хуже.", "title": "Техника и длительность"}], "steps": ["Перечитать свиток ступени и выписать главное от руки", "Первая близость — только когда хотите оба", "После: записать, что было хорошо и что улучшить"], "rank": "D", "after": ["women", 2]}], "lock": "D"}, {"id": "heart", "name": "Сердце чемпиона", "desc": "Тренировки, где борешься за каждую секунду.", "why": "Ядро тренинга «Тестостерон Релиз». Когда хочется бросить — сделать ещё 5–10%. Так воспитывается характер, и он переносится на всю жизнь.", "tiers": [{"n": 1, "mode": "days", "title": "Одна тренировка в неделю по силам", "how": "Любая: зал, мешок, бег, скакалка. План заранее.", "daily": "Тренировка по силам (раз в неделю)", "goal": "", "days": 21, "chapter": [{"check": "Хотя бы раз дошёл до конца, когда хотелось бросить.", "practice": "План тренировки заранее. Когда хочется остановиться — ещё 5–10%.", "text": "Ядро «Тестостерон Релиз»: научиться идти дальше, когда хочется бросить. Человек сдаётся не от усталости мышц, а когда мозг не видит близкого результата — и это тренируется.", "title": "Что такое Сердце чемпиона"}, {"practice": "Задай его себе после тренировки.", "text": "«Чего бы я достиг, если бы мне было плевать, получается или нет, — просто продолжал?»", "title": "Вопрос себе"}]}, {"n": 2, "mode": "days", "title": "2–3 тренировки в неделю, +5–10% сверх плана", "how": "Добавляй, когда хочется остановиться. Травма — пропуск и лечение.", "daily": "Тренировка +5–10% сверх плана", "goal": "", "days": 21, "chapter": [{"practice": "Добавляй, когда хочется остановиться.", "text": "Вес на 10 раз → с музыкой, «инкарнацией» героя и друзьями — до 15–20. Травма — пропуск и лечение, без геройства.", "title": "Железо и музыка"}]}, {"n": 3, "mode": "once", "title": "Большая сессия раз в месяц", "how": "Мешок 12 раундов, тест Купера или своё испытание.", "daily": "", "goal": ""}]}, {"id": "nose", "name": "Нос и дыхание", "desc": "Свободный нос и дыхание носом.", "why": "Арсен: без носового дыхания — депрессия, руминация, ангедония; обоняние — прямые «рельсы» к мозгу. Хроническая сухость носа — это обезвоживание. Плюс дыхание носом успокаивает нервную систему.", "tiers": [{"n": 1, "mode": "days", "title": "Промывка и нос на прогулке", "how": "Вечером промыть нос солёной водой (как «Долфин»). На прогулке дышать только носом.", "daily": "Промыть нос солью + дышать носом", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Ночью не дышишь ртом.", "practice": "Промывка перед сном, 1–2 раза в день.", "text": "Нет носового дыхания — мозг получает меньше кислорода, хуже сон, тянет к тревоге. Арсен сам 2–3 недели слезал с сосудосуживающих капель — теперь дышит носом.", "title": "Почему нос"}, {"check": "Держишь язык в нёбо без напоминаний.", "practice": "На прогулке: язык в нёбо, рот закрыт.", "text": "Язык корнем прижат к нёбу — это открывает нос и держит голову. Скажи «инга» и замри — вот положение.", "title": "Язык в нёбо"}]}, {"n": 2, "mode": "days", "title": "Стопы и вибрация", "how": "Стопы связаны с носоглоткой: 1–2 минуты в холодной воде и сразу согреть. Потом 3 минуты «ОМ» так, чтобы дрожали брови и кончик носа.", "daily": "Стопы в холодную воду + «ОМ» 3 минуты", "goal": "21 день практики (не обязательно подряд)", "days": 21}, {"n": 3, "mode": "steps", "title": "Проверить нос", "how": "Если нос заложен постоянно — к ЛОРу, при старых ударах — к остеопату. Спать с приподнятой головой.", "daily": "", "goal": "Сделать все шаги", "steps": ["Записаться к ЛОРу", "Если были удары по носу — к остеопату", "Неделю спать с приподнятой головой (подушка под лопатки)", "Записать, как изменился сон"]}]}, {"id": "mouth", "name": "Рот и зубы", "desc": "Здоровый рот без пасты и налёта.", "why": "Арсен: гигиена рта сильно определяет характер; плохой запах изо рта — знак, что организм не справляется. Главное для зубов — жевание.", "tiers": [{"n": 1, "mode": "days", "title": "Утро рта", "how": "Утром: щётка без пасты, потом ложка кокосового масла во рту 5 минут (гонять по всем зубам), выплюнуть. Постепенно до 15–20 минут.", "daily": "Щётка без пасты + масло во рту 5 минут", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Утром нет неприятного запаха.", "practice": "Кокосовое масло virgin, 5 минут утром.", "text": "Арсен никогда не чистит пастой: фтор и диоксид титана. Вместо неё — ойл-пуллинг кокосовым маслом, забрус, ирригатор.", "title": "Почему без пасты"}, {"check": "Дёсны не кровят.", "practice": "Жевать твёрдую еду (морковь, мясо) долго, вверх-вниз.", "text": "Зубы живут от кровотока в дёснах, а его даёт жевание. Организм рассчитан примерно на 30 минут жевания в день.", "title": "Жевать"}]}, {"n": 2, "mode": "days", "title": "Жевание и ирригатор", "how": "Ирригатор вечером. Днём — жевать твёрдое: морковь, забрус, смолу. Не качать челюсть тренажёрами.", "daily": "Ирригатор + жевать твёрдое долго", "goal": "21 день практики (не обязательно подряд)", "days": 21}, {"n": 3, "mode": "steps", "title": "Стоматолог", "how": "Вылечить кариес и сделать профчистку. Чем дольше ждать, тем дороже.", "daily": "", "goal": "Сделать все шаги", "steps": ["Найти стоматолога рядом", "Записаться (после зарплаты)", "Вылечить кариес", "Профчистка"]}]}, {"id": "officer", "name": "Норматив офицера", "desc": "Базовая сила, которую ты полностью контролируешь.", "why": "Арсен: качать шею и челюсть, отжиматься — узкая шея и тонкие запястья неприемлемы, это то, что ты полностью контролируешь. Звание — только после сдачи норматива. Твоя цель месяца — 20 отжиманий подряд.", "tiers": [{"n": 1, "mode": "steps", "title": "20 отжиманий подряд", "how": "Каждое утро в зарядке — на 1 отжимание больше. По воскресеньям — замер.", "daily": "", "goal": "20 подряд", "steps": ["Первый замер: сколько подряд сейчас", "Дойти до 10 подряд", "Дойти до 15 подряд", "20 подряд — цель месяца"]}, {"n": 2, "mode": "days", "title": "Шея и запястья", "how": "Шея: наклоны с сопротивлением ладони во все стороны. Запястья: сжимать эспандер или мяч, вращения кистями.", "daily": "5 минут: шея и запястья", "goal": "21 день практики (не обязательно подряд)", "days": 21}, {"n": 3, "mode": "steps", "title": "Сдать свой норматив", "how": "Свой «ГТО»: 50 отжиманий подряд, 10 подтягиваний, планка 2 минуты.", "daily": "", "goal": "Сдать норматив", "steps": ["Замер: отжимания, подтягивания, планка", "План на 6 недель", "Контрольный замер через 3 недели", "Сдать норматив — и никому не рассказывать до сдачи"]}], "fy": "20 отжиманий подряд — твоя первая цель (сейчас 15)."}, {"id": "fight", "name": "Бой", "desc": "Спокойно принимать риск получить в лицо.", "why": "Арсен: цель единоборств — психологически спокойно принимать риск получить в лицо. Заблокированная агрессия — корень мужской беды, а бой её разблокирует. Кёкусинкай учит стоять на своём без мелодрамы. Твоя мечта из Ила — бокс.", "tiers": [{"n": 1, "mode": "days", "title": "Бой с тенью", "how": "10 минут бой с тенью или мешок. Бить с выдохом, стойка, руки у лица. Можно под видео-уроки бокса.", "daily": "10 минут бой с тенью или мешок", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "После тренировки в голове тише.", "practice": "Злишься — 3 раунда по 2 минуты на мешок или в воздух.", "text": "Злость, которую держишь в себе, съедает силы лобных долей. Мешок и бой с тенью — безопасный выход.", "title": "Зачем бить"}]}, {"n": 2, "mode": "steps", "title": "Зал единоборств", "how": "Записаться на бокс или кёкусинкай и отходить месяц. После выхода на работу — это по деньгам.", "daily": "", "goal": "Месяц тренировок", "steps": ["Найти зал рядом (бокс или кёкусинкай)", "Пробное занятие", "Отходить 4 недели", "Записать: что изменилось в уверенности"]}, {"n": 3, "mode": "steps", "title": "Спарринг с сильнее", "how": "Арсен: никогда не отказываться от спарринга с тем, кто сильнее. Полгода бокса и выйти на любой открытый турнир — жизнь разделится на «до» и «после».", "daily": "", "goal": "Спарринг", "steps": ["Попросить тренера о спарринге с более сильным", "Выйти и отработать до конца", "Разобрать: что понял о себе"]}], "fy": "Если тянет — бокс или бой с тенью отлично сгоняют вес и страх."}, {"id": "energy", "name": "Природная энергия", "desc": "Направлять всплески энергии вверх, а не сливать.", "why": "Практика Арсена из «Тестостерон Релиз»: при каждом всплеске энергии (злость, возбуждение, маленькая победа) — не сливать её, а «поднимать» по позвоночнику. Идёт вместе с воздержанием.", "tiers": [{"n": 1, "mode": "days", "title": "Поднять всплеск", "how": "При всплеске: представить красную сферу внизу таза, луч по позвоночнику вверх и по всему телу. До 30 минут в день суммарно.", "daily": "Поднять всплеск энергии по позвоночнику", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "После всплеска — собранность, а не пустота.", "practice": "Почувствовал всплеск — 1 минута: сфера внизу таза, луч вверх по спине, по всему телу.", "text": "Злость, возбуждение, радость от победы — это энергия. Арсен учит не сливать её (в ленту, еду, дрочку), а поднимать по позвоночнику. Идёт в паре с воздержанием.", "title": "Не сливать всплеск"}]}, {"n": 2, "mode": "days", "title": "Заряд от побед", "how": "Заряд от общения и мелких побед поднимать наверх, не до возбуждения.", "daily": "Заряд от мелких побед — наверх", "goal": "21 день практики (не обязательно подряд)", "days": 21}, {"n": 3, "mode": "steps", "title": "Тотем", "how": "Образ-тотем + 20–25 секунд частого дыхания + луч от надпочечников — для тяжёлых подходов и экстремальных ситуаций.", "daily": "", "goal": "Освоить", "steps": ["Выбрать образ-тотем", "Попробовать перед тяжёлым подходом", "Записать ощущения"]}]}], "rows": [["walk", "sleep"], ["cold", "nose", "food", "mouth"], ["officer", "checkup", "sex"], ["heart", "fight"], ["energy"]], "parents": {"checkup": ["food"], "cold": ["walk"], "energy": ["heart", "sex"], "fight": ["officer"], "food": ["sleep"], "heart": ["officer"], "mouth": ["sleep"], "nose": ["walk"], "officer": ["walk", "cold"], "sex": ["sleep", "food"]}}, {"key": "socium", "p": "brave", "name": "Социум", "short": "свои люди и связи", "why": "Арсен: «семья — самое большое богатство», а самая большая ценность жизни — глубокие эмоциональные связи. Один из худших поступков — встретить своих людей и не узнать их. Расти лучше среди равных или чуть сильнее.", "skills": [{"id": "contact", "name": "Свои люди", "desc": "Живые связи с людьми, которые для тебя свои.", "why": "Самая большая ценность жизни, по Арсену, — глубокие эмоциональные связи: «счастье — когда не можешь умереть или заболеть незамеченным». Ощущение бессмысленности = нет связей.", "tiers": [{"n": 1, "mode": "days", "title": "Один живой контакт в день", "how": "Написать или позвонить своему человеку не по делу", "daily": "Написать или позвонить своему человеку не по делу", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Люди отвечают теплее.", "practice": "Написать или позвонить просто так, не по делу.", "text": "Урок Наруто по Арсену: быть инициатором связей самому. Не ждать, что позовут.", "title": "Инициатор — ты"}, {"practice": "В сообщении — одна тёплая конкретная фраза.", "text": "Теплота — первый фильтр людей: как ты говоришь, как относишься к чужим ошибкам. Будь как радиатор: грей сам, не жди, что согреют тебя.", "title": "Теплота"}, {"practice": "Подумай, кто для тебя по-настоящему свой.", "text": "Один из худших поступков — встретить своих и не узнать их или не остаться с ними.", "title": "Свои люди"}]}, {"n": 2, "mode": "days", "title": "Раз в неделю вживую", "how": "Раз в неделю встретиться вживую", "daily": "Раз в неделю встретиться вживую", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"practice": "Встречаться с теми, кто растёт.", "text": "«Мобы на 20 уровней ниже — 0 опыта; мобы своего уровня — хороший опыт». Спутников выбирать среди равных или чуть сильнее.", "title": "Своего уровня"}, {"practice": "Одна встреча в неделю с человеком, рядом с которым хочется быть лучше.", "text": "В слабой группе даже сильный падает до её норм, в сильной — растёт. Нормы группы становятся твоими.", "title": "Окружение задаёт планку"}, {"text": "Не вкладываться в неблагодарных: сначала человек показывает, что в него есть смысл вкладываться, потом вклад.", "title": "Сначала дело, потом вклад"}]}, {"n": 3, "mode": "days", "title": "Собрать своих", "how": "Раз в месяц собрать своих людей", "daily": "Раз в месяц собрать своих людей", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"text": "Главный принцип: «моя жизнь продолжается так же, как без тебя. Согласен — окей, нет — уходи». Спутник — тот, кто идёт по пути, а не сбивает.", "title": "Моя жизнь продолжается"}, {"text": "Смотри, как человек тебя выбирает, а не что говорит. Слушай людей «с выключенным звуком».", "title": "Лояльность — как тебя выбирают"}, {"practice": "Раз в месяц помочь или помирить кого-то, ничего не ожидая.", "text": "«Хочу, чтобы про меня сказали: он был из тех, кто не стрелял». Мирить, помогать без выгоды.", "title": "Сильная доброта"}]}], "fy": "Кроме Эдуарда почти никого — строим круг."}, {"id": "women", "name": "Женщины", "desc": "Перестать бояться женщин и найти свою — через состояние, а не через силу воли.", "why": "Арсен: женщина — самый прямой доступ к твоей энергии. Ты сам не можешь приказать себе быть энергичным, а она может: ты сделал дело — она восхищается, и сил становится больше. Но страх в лоб не ломается: «заставлять себя бесполезно, нужно менять внутреннее состояние».", "tiers": [{"n": 1, "mode": "days", "title": "Состояние вместо силы воли", "how": "День без порно и мастурбации", "daily": "День без порно и мастурбации", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Ты не винишь себя за то, что пока не подходишь.", "practice": "Пока не заставляй себя подходить к девушкам на силе воли. Сначала качаем состояние.", "text": "Арсен: если боишься подойти к женщине, никакие мотивационные речи не помогут. Действие против своего состояния — это «ручной режим», как первая поездка за рулём: мокрая спина, и выходит вымученно. Советы «делай много попыток, даже если страшно» дают те, кто уже в тонусе, а человеку без тонуса они наносят урон.", "title": "Почему «пересиль страх» не работает"}, {"check": "Желание сильнее страха: ловишь себя на том, что смотришь на девушек смелее.", "practice": "21 день без порно и мастурбации. Сорвался — без самобичевания, просто продолжай: дни не обязаны идти подряд.", "text": "Так Арсен сам победил страх женщин: ушёл в воздержание на 20 дней. «Меня сорвало крышу… Я так хотел, что уже не думал: можно, нельзя, боюсь, не боюсь». Когда очень хочешь пить, способ находишь сам.", "title": "Воздержание — его способ"}, {"check": "Здороваться с незнакомыми больше не напрягает.", "practice": "Магазин, лифт, зал, офис: «добрый день» каждому, глядя в глаза.", "text": "Базовые манеры Арсена: вставать, когда здороваешься, и здороваться со всеми в помещении — и с мужчинами, и с женщинами. Это маленький выход на контакт каждый день, без всяких ставок.", "title": "Здороваться со всеми"}], "watch": [{"min": 10, "title": "Women", "where": "база «Тестостерон релиз» в Телеграме"}], "rank": "D"}, {"n": 2, "mode": "steps", "title": "Среди людей, в своей тарелке", "how": "Ходить туда, где ты в силе и где есть девушки", "daily": "Ходить туда, где ты в силе и где есть девушки", "goal": "сделать один раз", "chapter": [{"check": "Ходишь туда, потому что нравится, а не «ради знакомств».", "practice": "Выбери место, где тебе в кайф и где есть девушки: зал, бокс, танцы, курсы, клуб по интересам. Ходи 4 недели.", "text": "В 13 лет Арсен подошёл к трём девушкам 18–19 лет. Поймал взгляд, понял, что понравился, подошёл, поел их чипсов и ушёл. Он был в тонусе, поэтому всё получилось само. Знакомство складывается там, где ты в своей тарелке.", "title": "Играть там, где ты в силе"}, {"check": "Разговор с девушкой случился сам, без плана.", "practice": "Цель похода — само занятие. Девушки — не задача, а то, что может случиться.", "text": "«Чем менее мы зависимы от конечного результата и чем менее мы его хотим, тем лучше он будет получаться». Звучит странно, но это так.", "title": "Меньше хотеть результата"}, {"check": "Взгляды больше не хочется отводить.", "practice": "Встретился взглядом — задержи его на пару секунд и улыбнись. Ошибся при всех — посмейся вместе.", "text": "Арсен «по глазам понял», что понравился. Взгляд в ответ и улыбка — уже приглашение. Упал на роликах, все смеются — по Арсену, это отличный повод заговорить с той, кто смеялась.", "title": "Читать взгляд"}], "steps": ["Выбрать место, где тебе в кайф и где есть девушки", "Сходить: неделя 1", "Сходить: неделя 2", "Сходить: неделя 3", "Сходить: неделя 4"], "watch": [{"min": 45, "title": "Эфир 22 января 2023 (про тонику)", "where": "база «Тестостерон релиз» в Телеграме"}], "rank": "D"}, {"n": 3, "mode": "steps", "title": "Первое свидание", "how": "Пригласить девушку на простую встречу", "daily": "Пригласить девушку на простую встречу", "goal": "сделать один раз", "chapter": [{"check": "Позвал и не прокручивал это потом весь вечер.", "practice": "Одна короткая фраза с местом и временем. Отказ — это её ответ, а не оценка тебя.", "text": "Кофе или прогулка. Арсен: в лоб ничего не работает, никаких «я вожак, слушайся». Работает лёгкая игра, которую ведёшь ты.", "title": "Пригласить просто"}, {"check": "Ей рядом с тобой спокойно.", "practice": "На встрече будь спокойным и тёплым: веди, предлагай, решай, но с заботой.", "text": "Женщине от мужчины нужна гарантия физической и эмоциональной безопасности: сила и тепло вместе. Сильный, но холодный — для неё враг. Тёплый, но слабый — просто друг. Нужно и то и другое.", "title": "Что ей нужно"}, {"check": "Выбираешь ты, а не только выбирают тебя.", "practice": "После встречи спроси себя: мне с ней хочется делать больше или меньше?", "text": "Хорошая женщина закрепляет твои дела: ты сделал — она рада и гордится тобой. «Сломанная» тянет из дел: «ты только работаешь, когда мы будем вместе». По Арсену, лучше одному, чем с кем попало: вода пополам с соком — самое противное.", "title": "Фильтр"}, {"check": "Уходишь без обиды и злости.", "practice": "Не доказывай, не уговаривай. Не твоё — спокойно уйди.", "text": "Арсен уходит со свидания через 15 минут, если видит, что он для человека не ценность. Любовь не выпросить.", "title": "Ты — ценность"}], "steps": ["Пригласить девушку на кофе или прогулку", "Сходить на встречу", "После встречи ответить себе: с ней хочется делать больше или меньше?"], "watch": [{"min": 10, "title": "Кто такие хорошие женщины", "where": "база «Тестостерон релиз» в Телеграме"}, {"min": 5, "title": "Завоевание женского внимания", "where": "база «Тестостерон релиз» в Телеграме"}], "rank": "D"}], "fy": "Откроется с ранга D. Сначала смелость, тело и образ.", "lock": "D"}, {"id": "parents", "name": "Родители", "desc": "Принятие и связь с родителями.", "why": "Принятие родителей у Арсена — основа внутренней силы: «ТР — это тренинг по приятию отца». Отблагодарить, а не «обеспечить». Не бояться, что уйдут, — думать, как порадовать.", "tiers": [{"n": 1, "mode": "days", "title": "Раз в неделю позвонить и сказать, что ценишь", "how": "Просто так, без повода.", "daily": "Раз в неделю позвонить родителям", "goal": "", "days": 21, "chapter": [{"check": "Разговор без претензий.", "practice": "Раз в неделю звонок просто так.", "text": "Арсен: говорят «обеспечить» о недееспособных. Родителей — отблагодарить, сделать приятно. «Позвоните родителям, скажите, что цените и любите».", "title": "Отблагодарить, а не «обеспечить»"}, {"practice": "Волшебная фраза: «Я рад тебя слышать, но буду говорить только на интересные мне темы».", "text": "Приятие — не любовь и не трепет: «смотреть можно, руками не трогать». Не учить и не исправлять их.", "title": "Экспонат в музее"}]}, {"n": 2, "mode": "once", "title": "Расспросить историю семьи", "how": "Родовое древо, как жили деды, откуда род.", "daily": "", "goal": "", "chapter": [{"practice": "Родовое древо, как жили деды, откуда род.", "text": "Пока родители живы — вытяни из них всю семейную историю. Они будут рассказывать нехотя.", "title": "История семьи"}]}, {"n": 3, "mode": "once", "title": "Сказать то, что давно не сказал", "how": "Упражнение Арсена: устать на мешке или отжиманиях и вслух повторять «Я сын [имя отца]».", "daily": "", "goal": ""}], "fy": "Родители подгоняют — это забота. Им важно видеть, что ты растёшь."}, {"id": "debts", "name": "Эмоциональные долги", "desc": "Закрыть старые невысказанные вещи.", "why": "Ваагн: раздел с самым быстрым эффектом. Каждое несказанное «спасибо» и «прости» висит в голове и жрёт энергию.", "tiers": [{"n": 1, "mode": "once", "title": "Сказать одно давно невысказанное «спасибо»", "how": "Лично, сообщением или звонком.", "daily": "", "goal": "", "chapter": [{"check": "Стало легче.", "practice": "Одно давно невысказанное «спасибо» — лично, сообщением или звонком. Твоя задача «Поблагодарить всю семью» — отсюда.", "text": "Ваагн: несказанное «спасибо» висит в голове и жрёт энергию фоном. Арсен: благодарность — это всегда содействие.", "title": "Спасибо"}]}, {"n": 2, "mode": "once", "title": "Одно «прости» тому, перед кем реально виноват", "how": "Без оправданий.", "daily": "", "goal": ""}, {"n": 3, "mode": "once", "title": "Письмо обиде и сжечь", "how": "Выписать всё, что хочешь сказать, подписать, сжечь. Мозг не видит разницы.", "daily": "", "goal": "", "chapter": [{"practice": "Твоя задача «Письмо дяде Лёше» — близко к этому.", "text": "Пролактин высок, когда хочешь сказать и не можешь. Написать всё, подписать и сжечь — мозг не видит разницы.", "title": "Письмо и сжечь"}]}]}, {"id": "boundaries", "name": "Границы", "desc": "Право сказать «нет» и остановить неуважение.", "why": "«Не верь, не бойся, не проси — и не объясняй». Границы ставятся в нулевую секунду: пресёк сразу — к тебе относятся всерьёз.", "tiers": [{"n": 1, "mode": "once", "title": "Одно «нет» без объяснений", "how": "В безопасной ситуации.", "daily": "", "goal": "", "chapter": [{"check": "Сказал «нет» и не извинялся.", "practice": "Одно «нет» в безопасной ситуации, без оправданий: «мне так неудобно, поэтому будет так».", "text": "Арсен: «Без права отказать — перманентная жертва». Отказывать можно без объяснения причин. Твоя задача «Учиться говорить нет» — отсюда.", "title": "Право на отказ"}, {"practice": "Сделал — сообщил, без просьбы о разрешении.", "text": "«Тот, кто берёт на себя бремя объяснения, — терпила». Объяснение воспринимается как нападение. Сначала делаешь, потом ставишь перед фактом.", "title": "Не объяснять"}]}, {"n": 2, "mode": "days", "title": "Граница в нулевую секунду раз в неделю", "how": "Спокойно остановить неуважение сразу, а не потом в голове.", "daily": "Граница в нулевую секунду", "goal": "", "days": 21, "chapter": [{"practice": "Раз в неделю: остановить неуважение в моменте, а не потом в голове.", "text": "Неуважение видно сразу. Поблажка тому, кто проявил неуважение, ни разу не окупилась. Пресекать спокойно, сразу.", "title": "Нулевая секунда"}]}, {"n": 3, "mode": "once", "title": "Правила моей игры", "how": "Записать свои правила с людьми и начать жить по ним. «Нравится — заходи».", "daily": "", "goal": ""}], "fy": "Ты слишком добрый и соглашаешься на лишнее — это про тебя."}, {"id": "circle", "name": "Окружение", "desc": "Кто вокруг тебя.", "why": "«Мобы на 20 уровней ниже — 0 опыта; мобы своего уровня — хороший опыт». Окружение задаёт твою планку: в сильной группе растут нормы.", "tiers": [{"n": 1, "mode": "once", "title": "Список: кто усиливает, кто высасывает", "how": "Честно, для себя.", "daily": "", "goal": "", "chapter": [{"check": "У каждого человека в списке есть пометка «после общения».", "practice": "После встречи с человеком из списка — ответь на три вопроса. Два «да» — ставим границу, а не рвём сразу (Лимарев: дозировать, не рвать).", "text": "Resolve: смотри, что чувствуешь ПОСЛЕ разговора. Три вопроса: выжат? давили? было страшно перед разговором? Два «да» — связь разрушительная.", "title": "Проверка после общения"}]}, {"n": 2, "mode": "once", "title": "Отдалить одного, кто тянет вниз", "how": "Без драмы, просто меньше времени.", "daily": "", "goal": ""}, {"n": 3, "mode": "once", "title": "Выйти на связь с человеком сильнее", "how": "Наставник, старший, профессионал. Есть Эдуард — это уже шаг.", "daily": "", "goal": ""}], "fy": "Эдуард тянет вверх. Ищи ещё таких."}, {"id": "warmth", "name": "Теплота", "desc": "Каким ты бываешь с людьми.", "why": "«Теплота — первый фильтр людей». Будь как радиатор: окатывай теплом сам, а не жди, что окатят тебя. Смотри на людей с планкой выше, чем они сами.", "tiers": [{"n": 1, "mode": "days", "title": "Одна искренняя похвала или помощь в день", "how": "Без выгоды.", "daily": "Одна искренняя похвала или помощь", "goal": "", "days": 21, "chapter": [{"check": "Вечером: где я сегодня сделал светлее?", "practice": "Одна искренняя похвала или помощь в день, без выгоды.", "text": "Арсен: будь как радиатор — окатывай теплом сам, а не жди, что окатят тебя. Смотри на людей с планкой выше, чем они сами на себя смотрят.", "title": "Радиатор"}]}, {"n": 2, "mode": "once", "title": "Сильная доброта", "how": "Помирить кого-то или помочь серьёзно, ничего не ожидая.", "daily": "", "goal": ""}, {"n": 3, "mode": "once", "title": "Стать опорой для одного человека", "how": "Регулярно поддерживать того, кто растёт.", "daily": "", "goal": ""}]}, {"id": "people", "name": "Видеть людей", "desc": "Нейротипология: читать людей по лицу и поведению.", "why": "Лимарев: навык нейротипологии — понять свой тип, перестать сравнивать себя с чужим темпом и найти 2–3 «версии себя», которые уже там, где ты хочешь быть. Арсен: выбирай людей, как 7-летний чувствует добрую продавщицу; о человеке говорят 2–3 ярких факта. Ты сам сказал: это навык «видеть людей насквозь».", "tiers": [{"n": 1, "mode": "days", "title": "10 минут в людях", "how": "Начать с себя: интроверт или экстраверт, какая зона лица главная (верх, середина, низ). Потом каждый день — один человек: какой он, как поведёт себя в кризисе.", "daily": "10 минут: разобрать одного человека", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Можешь объяснить свой тип одной фразой.", "practice": "Записать: где я заряжаюсь — один или с людьми.", "text": "Лимарев: себя не надо мерить по чужой мерке — нужно точно знать свою психику. Первый шаг — интроверт я или экстраверт.", "title": "Сначала себя"}, {"check": "Предсказание поведения хоть раз сбылось.", "practice": "На встрече заметь одну черту лица и что она может значить.", "text": "Лимарев: «я тебя изучаю, мне не всё равно, с кем я общаюсь». Поджатая прямая верхняя губа — хронически сдерживаемое недовольство.", "title": "Смотреть «нагло» можно"}]}, {"n": 2, "mode": "steps", "title": "Разобрать своих", "how": "Разобрать себя и 5 близких: тип, зона лица, как ведут себя в кризисе.", "daily": "", "goal": "6 разборов", "steps": ["Разбор себя", "Разбор 2 родных", "Разбор 2 друзей (например, Коля)", "Разбор 1 человека из жизни: семья, знакомые, люди на работе", "Сравнить: где угадал, где нет"]}, {"n": 3, "mode": "steps", "title": "Версии себя", "how": "Лимарев: найти 2–3 человек своего типа, которые уже там, где ты хочешь быть (из комнаты с ноутом → свои релизы и аудитория), и копировать их решения и распорядок.", "daily": "", "goal": "Сделать все шаги", "steps": ["Найти 3 «версии себя» (блог, интервью, знакомые)", "Выписать их распорядок и решения", "Взять одну их привычку на месяц"]}]}, {"id": "diplomacy", "name": "Дипломатия", "desc": "Решать споры, не воюя и не сдаваясь.", "why": "Лимарев: дипломатия — «победить, не побеждая и не проигрывая», быть медиатором, переводить позиции сторон друг другу. Арсен: 99% конфликтов — сбой связи, а не настоящий спор; перескажи собеседнику его мысль его словами. У тебя: трудно говорить «нет», соглашаешься на то, чего не хочешь.", "tiers": [{"n": 1, "mode": "days", "title": "Пересказать его словами", "how": "Прежде чем отвечать, пересказать собеседнику его мысль его же словами: «правильно понимаю, что ты…?». Говорить о себе и своих чувствах («я не чувствую поддержки»), а не приговаривать («ты всегда…»).", "daily": "В споре — пересказать мысль другого его словами", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Спор закончился без обиды.", "practice": "Без «всегда», «никогда», «да ты…».", "text": "Большинство споров — не спор, а разные картины мира. Навык — воссоздать у себя в голове смыслы другого.", "title": "Сбой связи"}]}, {"n": 2, "mode": "steps", "title": "Быть медиатором", "how": "Помочь двум людям договориться: выслушать обоих и перевести позиции друг другу.", "daily": "", "goal": "Один помиренный спор", "steps": ["Выслушать первую сторону и пересказать её", "Выслушать вторую", "Перевести каждому позицию другого", "Найти решение, где никто не проиграл"]}, {"n": 3, "mode": "steps", "title": "Флегма на давление", "how": "Арсен: на давление и манипуляцию — не игнор и не бурная реакция, а ровный однозначный ответ 2–3 недели без эмоций.", "daily": "", "goal": "Выдержать", "steps": ["Назвать ситуацию, где на тебя давят", "Решить свой ответ одной фразой", "Отвечать ровно и одинаково 2 недели", "Записать итог"]}]}, {"id": "triad", "name": "Тёмная триада: броня", "desc": "Узнавать нарциссов, манипуляторов и психопатов по поступкам, не поддаваться их приёмам и уверенно торговаться.", "why": "Такие люди есть среди начальников, знакомых и «друзей». Кто видит приём, на того он не действует. Арсен: стыд и совесть — рычаг «сверху вниз»; управлять человеком — значит управлять его ожиданиями.", "tiers": [{"n": 1, "mode": "steps", "title": "Распознать", "how": "Прочитать свиток, пройти самопроверку в «Знаниях», разобрать трёх человек из жизни по поступкам — без диагнозов.", "daily": "", "goal": "Видеть черту по поступкам, а не по словам и обаянию.", "chapter": [{"check": "Могу своими словами объяснить три черты.", "practice": "Вспомни одного человека, после общения с которым ты чувствовал себя хуже, чем до. Просто запиши его имя.", "text": "Три черты характера, которые психологи Полхус и Уильямс описали вместе в 2002 году: нарциссизм, макиавеллизм и психопатия. Это не диагнозы, а черты — они есть у всех понемногу. Опасно, когда они сильные и сходятся в одном человеке. Иногда добавляют четвёртую — бытовой садизм (удовольствие от чужой боли), тогда говорят «тёмная тетрада». Общее ядро у всех: холодность к другим и готовность использовать людей.", "title": "Что такое тёмная триада"}, {"practice": "В одном разговоре посчитай, сколько раз тема вернулась к собеседнику.", "text": "Жажда восхищения, ощущение своей особости, зависть, непереносимость критики. Признаки: разговор всегда возвращается к нему; твои успехи обесценивает или присваивает; сначала идеализирует, потом обесценивает; на мягкое замечание — обида или ярость; правила — для других. Бывает громкий (хвастается) и тихий (непонятый обиженный гений).", "title": "Нарцисс"}, {"practice": "Заметь, кто в твоём окружении рассказывает разным людям разное.", "text": "Холодный стратег: люди для него — ресурс, цель оправдывает средства, играет вдолгую. Признаки: говорит то, что ты хочешь услышать; разным людям — разные версии; просит «только между нами»; помогает, а потом напоминает о долге; меняет правила по ходу игры; льстит перед просьбой.", "title": "Макиавеллист"}, {"practice": "Вспомни, когда человек соврал и не смутился. Что ты тогда сделал?", "text": "Мало сочувствия и страха, импульсивность, тяга к острым ощущениям, нет чувства вины, поверхностное обаяние. Признаки: быстрый шарм и близость («как будто знаем друг друга сто лет»); легко и уверенно врёт, а пойманный — не смущается; рискует за чужой счёт; жалеет себя, но не других; нарушает договорённости без объяснений.", "title": "Психопат (бытовой)"}, {"check": "Отличаю «неприятный человек» от «меня используют».", "practice": "Неделю после каждого тяжёлого разговора пиши одну строку: что я чувствую и что он сделал.", "text": "Тело сигналит раньше головы: ощущение, что ты должен; путаница «может, это я не так понял»; хочется оправдываться; после разговора — усталость и сомнение в себе. Правило: суди по поступкам за время, а не по словам и обаянию. Диагнозы ставить не нужно — достаточно видеть узор «берёт больше, чем даёт, и после него я слабее». Арсен: «люди ведут себя как газ — занимают всё пространство, которое им даёшь».", "title": "Главный признак — как ты себя чувствуешь"}], "steps": ["Прочитать свиток «Распознать» (5 глав)", "Самопроверка: 8 ситуаций в «Знаниях → Броня: самопроверка», угадать минимум 6", "Вспомнить 3 людей, с кем было тяжело: по каждому 2–3 поступка → какая черта (или никакой)", "Записать один приём давления, который на мне сработал, и что я тогда почувствовал"]}, {"n": 2, "mode": "days", "title": "Не поддаться", "how": "Каждый день заметить один приём давления — на себе, в переписке, в рекламе — и ответить по скрипту или хотя бы назвать его про себя.", "daily": "Броня: заметить 1 приём давления и ответить", "goal": "21 день — приёмы узнаются на автомате.", "days": 21, "chapter": [{"practice": "Выбери 3 приёма, которые на тебе срабатывают чаще всего.", "text": "Газлайтинг («тебе показалось», «я такого не говорил»). Лавбомбинг — засыпают вниманием, потом отбирают. Вина и стыд («как тебе не стыдно», «я для тебя всё…»). Срочность («только сегодня», «решай сейчас»). Обесценивание («это любой может»). Триангуляция — сравнение с третьим («а вот Саша бы…»). Молчаливое наказание — игнор, чтобы ты сам прибежал. Перекладывание («ты меня довёл»). Ложный выбор («или так, или никак»). «Побудь на моём месте». Маленькая просьба, за которой идёт большая. Лесть перед просьбой.", "title": "Приёмы давления"}, {"practice": "Выучи наизусть две фразы: «Может быть. И всё равно нет.» и «Мне нужно подумать, отвечу завтра.»", "text": "«Туман» — частично соглашаешься, не уступая: «Может быть, ты прав. И всё равно я сделаю так». «Заезженная пластинка» — спокойно повторяешь отказ без новых объяснений, хоть три раза. Пауза 6 секунд, когда накрывает эмоция. Против срочности: «Мне нужно подумать, отвечу завтра». Против газлайтинга: «Давай запишу, о чём договорились». «Серый камень» — скучные короткие ответы без эмоций, которыми он питается. Вопрос стоиков: «Это в моей власти?» Проверка: «А если бы это сказал посторонний — я бы согласился?»", "title": "Ответы"}, {"practice": "Почувствовал вину — спроси: у просящего есть реальная причина или только давление?", "text": "Арсен: стыд и совесть включают, когда реальных причин нет. Снизу вверх стыд не работает — это напоминание тебе о «низком ранге». Ответ: опираться на свои принципы, а не на чувство вины. «Побывать на месте» соглашайся не в этой минуте, а во всей жизни человека: «на твоём месте я бы до этой точки не дошёл». И не отдавай своё из «неловкости победителя».", "title": "Когда давят стыдом"}, {"practice": "Про одного тяжёлого человека реши: дистанция, серый камень или границы — и сделай первый шаг.", "text": "Если такой человек близко: минимум информации о своих слабостях — «не рассказывай, где у тебя болит»; не спорь по существу, всё равно не переспоришь; фиксируй письменно; держи дистанцию; опирайся на своих людей. На работе — письменно, при свидетелях, через процесс.", "title": "Выход"}]}, {"n": 3, "mode": "steps", "title": "Переговоры и торг", "how": "Подготовить и провести торг: зарплата, график, цена вещи, условия.", "daily": "", "goal": "Назвать свою цифру первым, выдержать молчание и не уступить себе раньше ответа.", "chapter": [{"practice": "Скажи вслух 5 раз свою цифру ровным голосом, без «ну…» и «примерно».", "text": "Первая названная цифра тянет всю сделку к себе. Называй первым, верх своей вилки, с обоснованием. Назвали их цифру — не отталкивайся от неё, верни разговор к своей. Это продолжение навыка «Цена „вправе“».", "title": "Якорь"}, {"practice": "В следующем разговоре после своего предложения молча досчитай до 7.", "text": "После своего предложения молчи: кто заговорил первым — тот и уступает. «Нужно ответить сегодня» — «мне нужны сутки». Не торгуйся с собой: не снижай цифру, пока тебе не ответили.", "title": "Молчание и время"}, {"practice": "Запиши свой лучший запасной вариант на случай отказа.", "text": "Сила в переговорах — насколько тебе не страшно уйти. Запасные варианты — твоя сила: когда есть выбор, на тебя сложно давить. Запасной вариант держи в голове, а не на столе.", "title": "Запасной вариант"}, {"practice": "Составь список из 5 вещей кроме денег, которые можно выторговать.", "text": "Не называй цифру в анкете раньше времени: «обсуждаемо под задачи». Сначала выясни задачи и ценность, потом цифра. Торгуются не только деньги: удалёнка, график, пересмотр через 3 месяца, бонус за результат, обучение. Всё итоговое — письменно.", "title": "Торг"}], "steps": ["Узнать рынок: вилки по 5 похожим вакансиям", "Записать свою нижнюю границу и запасной вариант (что сделаю, если не договоримся)", "Подготовить якорь: верх своей вилки + 3 аргумента с цифрами из кейсов", "Прогнать торг вслух с другом или с Claude", "Провести настоящий торг: после своей цифры — молчать"]}]}, {"id": "boldness", "name": "Смелость в людях", "desc": "Спокойно быть собой среди людей: громко, в глаза, с прямой спиной.", "why": "Страх людей — это не характер, а натренированная реакция. Она перенастраивается маленькими победами каждый день и строкой «я это смог» вечером.", "tiers": [{"n": 1, "mode": "days", "title": "Три смелые мелочи", "how": "Каждый день: хотя бы раз сказать громче обычного (больше воздуха), посмотреть человеку в глаза до конца фразы, пройтись с раскрытыми плечами. Вечером в журнал — одна строка «я это смог».", "daily": "Три смелые мелочи: громко, в глаза, прямая спина + вечером «я это смог»", "goal": "21 день", "days": 21, "chapter": [{"practice": "После каждого страшного дела — одна строка «я это смог».", "text": "Мозг запоминает победы, только если их засчитать. Одна строка после звонка, собеса или разговора — маленький опыт «я могу».", "title": "Победа над страхом — строкой"}, {"practice": "Перед фразой — вдох животом.", "text": "Тихий голос — сигнал «я не имею права». Громкость идёт от дыхания, а не от крика.", "title": "Громче — это больше воздуха"}]}, {"n": 2, "mode": "steps", "title": "5 маленьких разговоров", "how": "Пять коротких разговоров с незнакомыми: кассир, бариста, прохожий, сосед, охранник. Не ради результата — ради привычки.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"practice": "Один разговор в день.", "text": "Сколько ни читай о смелости, она появляется от сделанного. Пять лёгких разговоров сильнее сотни прочитанных советов.", "title": "Опыт — только в попытках"}], "steps": ["Спросить у кассира, как у него день", "Спросить дорогу, даже если знаешь", "Сделать комплимент бариста за кофе", "Поздороваться и перекинуться парой фраз с соседом", "Задать вопрос охраннику или администратору", "Записать, что почувствовал после пятого"]}, {"n": 3, "mode": "days", "title": "Героический шаг", "how": "7 дней подряд в день хорошего ресурса делать один «героический» социальный шаг: позвонить тому, кого боишься, выступить, попросить о большем, заговорить первым там, где обычно молчишь.", "daily": "", "goal": "7 дней", "days": 7, "chapter": [{"practice": "Проверь сон и еду перед шагом.", "text": "Героический шаг — в день, когда выспался и сыт. В разбитом состоянии он превращается в поражение и закрепляет страх.", "title": "Ресурс сначала"}], "steps": ["День 1: позвонить, а не написать", "День 2: попросить о большем, чем обычно", "День 3: сказать своё мнение на встрече", "День 4: заговорить первым с незнакомым", "День 5: отказать там, где обычно соглашаешься", "День 6: выступить или записать видео", "День 7: записать, что изменилось"], "rank": "B"}], "fy": "Громко, в глаза, с прямой спиной — без героизма."}, {"id": "selfworth", "name": "Нарцисс: самоценность", "desc": "Сейчас: извиняюсь за своё место и отдаю лучшее → Цель: занимаю своё место и спокойно принимаю признание", "why": "Нарциссизм в здоровой дозе — это самоценность: «я стою столько, сколько стою». Это не про то, чтобы стать злым. Ты слишком добрый и позволяешь лишнее — значит, сдвигаемся в сторону твёрдости, пока не найдёшь свою середину. Сочувствие оставляем: у Арсена в сильной личности оно третья составляющая. Баланс находится только в практике.", "tiers": [{"n": 1, "mode": "steps", "title": "Принять похвалу", "how": "Три раза за неделю ответить на похвалу только «спасибо».", "daily": "", "goal": "Принимать комплимент без оправданий.", "steps": ["Услышал комплимент — ответить «спасибо» и замолчать", "Не добавлять «да ладно», «это ерунда», «повезло»", "Вечером записать, как это было"]}, {"n": 2, "mode": "steps", "title": "Своё место в разговоре", "how": "Пять дней не извиняться без вины и один раз в разговоре назвать свой результат в цифрах без смягчений.", "daily": "", "goal": "Говорить о своём результате прямо.", "steps": ["5 дней без «извини» там, где не виноват", "Первым назвать своё мнение в одном разговоре", "Назвать результат в цифрах: «я сделал X, получилось Y»"]}, {"n": 3, "mode": "steps", "title": "Стена побед", "how": "Записать 10 своих побед и рассказать об одной на собеседовании или в важном разговоре без «но».", "daily": "", "goal": "Помнить свои победы и говорить о них громко.", "steps": ["Записать 10 побед из жизни", "Выбрать 3 главные в цифрах", "Рассказать одну вслух без «но» и «просто»"]}], "fy": "Ты сказал, что гордиться нечем. Этот навык это лечит."}, {"id": "calc", "name": "Макиавелли: расчёт", "desc": "Сейчас: верю на слово и говорю всё как есть → Цель: вижу интересы людей, держу информацию и веду переговоры", "why": "Макиавеллизм в здоровой дозе — это расчёт без обмана: смотреть, чего хочет другой, и не отдавать всё сразу. Мы не учимся врать или использовать людей. Это не про то, чтобы стать злым. Ты слишком добрый и позволяешь лишнее — значит, сдвигаемся в сторону твёрдости, пока не найдёшь свою середину. Сочувствие оставляем: у Арсена в сильной личности оно третья составляющая. Баланс находится только в практике.", "tiers": [{"n": 1, "mode": "steps", "title": "Чей интерес", "how": "В трёх ситуациях записать: чего он хочет и что выиграет.", "daily": "", "goal": "Видеть, чего хочет другой человек.", "steps": ["Выбрать 3 ситуации (работа, семья, знакомый)", "Для каждой: чего он хочет и что выиграет от моего «да»", "Вечером сверить с тем, что случилось"]}, {"n": 2, "mode": "steps", "title": "Не всё сразу", "how": "Три дня никому не рассказывать план заранее (глубинное молчание) и один раз ответить «подумаю до завтра».", "daily": "", "goal": "Не отдавать информацию и решения в первую секунду.", "steps": ["3 дня не рассказывать планы и цели", "Один раз ответить «подумаю до завтра» вместо мгновенного «да»", "Записать, что изменилось"]}, {"n": 3, "mode": "steps", "title": "Три хода вперёд", "how": "Перед собеседованием или разговором о деньгах расписать три хода вперёд и запасной вариант.", "daily": "", "goal": "Готовиться к важному разговору как к партии.", "steps": ["Написать мою цель, минимум и уход", "Расписать 3 хода собеседника и мои ответы", "Провести разговор и разобрать, что сработало"]}]}, {"id": "coldhead", "name": "Психопат: холодная голова", "desc": "Сейчас: чувство вины и страх решают за меня → Цель: спокойно выдерживаю давление и говорю «нет» без вины", "why": "Психопатия в здоровой дозе — это холодная голова: вина и страх не управляют тобой. Мы не учимся быть бесчувственными к людям. Это не про то, чтобы стать злым. Ты слишком добрый и позволяешь лишнее — значит, сдвигаемся в сторону твёрдости, пока не найдёшь свою середину. Сочувствие оставляем: у Арсена в сильной личности оно третья составляющая. Баланс находится только в практике.", "tiers": [{"n": 1, "mode": "steps", "title": "Нет без вины", "how": "Три раза за неделю отказать коротко: «нет, не смогу». Без оправданий.", "daily": "", "goal": "Отказывать без объяснений и извинений.", "steps": ["Отказать три раза без «извини» и без причины", "После каждого вдох на 4 счёта и 10 секунд холода в душе", "Вечером записать, что почувствовал и что случилось на самом деле"]}, {"n": 2, "mode": "steps", "title": "Не вестись на вину и жалость", "how": "Заметить три попытки надавить на вину или жалость и ответить спокойно: «понимаю, но нет».", "daily": "", "goal": "Узнавать давление через вину и жалость.", "steps": ["Заметить 3 такие попытки за неделю", "Каждый раз ответить спокойно, без спора", "Решение моё, сочувствие оставляю"]}, {"n": 3, "mode": "steps", "title": "Спокойствие на риске", "how": "Раз в неделю сделать одно страшное дело (звонок, цена, отказ) и сказать себе «страшно — значит будет хорошо».", "daily": "", "goal": "Делать страшное с холодной головой.", "steps": ["Выбрать страшное дело недели", "Сделать его в один шаг, не откладывая", "Записать: что стало на самом деле"]}], "fy": "Красный, горло сохнет? Холодная голова тренируется."}], "rows": [["contact", "triad"], ["people", "parents", "boundaries", "calc"], ["boldness", "debts", "circle", "selfworth", "coldhead"], ["diplomacy", "warmth"], ["women"]], "parents": {"boldness": ["people"], "boundaries": ["triad"], "calc": ["triad"], "circle": ["boundaries"], "coldhead": ["boundaries", "triad"], "debts": ["parents"], "diplomacy": ["boldness", "circle"], "parents": ["contact"], "people": ["contact"], "selfworth": ["boundaries"], "warmth": ["debts"], "women": ["diplomacy"]}}, {"key": "obrazy", "p": "look", "name": "Образы", "short": "как тебя видят и слышат", "why": "Образ работает на тебя, даже когда тебя нет в комнате. Людей цепляет «флюид»: застывшая эмоция на лице, походка, голос. Многое держится на теле: язык в нёбо собирает всю голову, зажатая челюсть даёт зажатость в общении.", "skills": [{"id": "jaw", "name": "Челюсть и язык", "desc": "Положение языка и работа челюсти.", "why": "«Язык — точка сборки головы». Челюсть связана с мозгом напрямую, и её зажатость даёт зажатость в общении, вплоть до социофобии. Правильный язык открывает нос, а без носового дыхания растут тревога и руминация.", "tiers": [{"n": 1, "mode": "days", "title": "5 минут: язык в нёбо, пробка, осанка", "how": "5 минут: язык в нёбо, пробка во рту, осанка", "daily": "5 минут: язык в нёбо, пробка во рту, осанка", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Язык сам лежит в нёбе.", "practice": "В течение дня ловить себя: где язык? Возвращать в нёбо.", "text": "Корень языка давит в нёбо — скажи «инг» и замри. Так лежит язык у спящего младенца, это единственное нормальное положение. Даёт прилив сил, держит голову и открывает нос.", "title": "Язык — точка сборки"}, {"check": "Челюсть мягче, приятное ощущение раскрытия.", "practice": "5 минут вечером, у телевизора или в ванной. Аккуратно, не порви уголки рта.", "text": "Пробка от бутылки во рту на 2–10 минут растягивает зажатую челюсть. Заодно размять бугорок жевательной мышцы у уха и простучать пальцами от виска до угла челюсти.", "title": "Пробка"}, {"practice": "Затылком тянуться назад, как будто упираешься им в стену.", "text": "Затылок за линией позвоночника, подбородок чуть вниз. Не подпирать челюсть рукой и не сидеть, сползая в кресле.", "title": "Голова на месте"}], "watch": [{"min": 22, "title": "Эфир про носовое дыхание", "where": "база «Тестостерон релиз» в Телеграме"}]}, {"n": 2, "mode": "days", "title": "+ правильное глотание", "how": "5 минут челюсти + 10 раз глотать правильно", "daily": "5 минут челюсти + 10 раз глотать правильно", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Нос дышит лучше.", "practice": "10 раз в день сглотнуть слюну правильно.", "text": "Язык прижат к нёбу, лицо неподвижно, глотаешь без щёк. Запускает отток из пазух, уходят заложенность и ангины.", "title": "Правильное глотание"}, {"practice": "Морковь, орехи, мясо — жевать вертикально.", "text": "Жевать строго вверх-вниз, а не перетирать. Перетирание, по Арсену, будит «травоядные» черты. Твёрдая еда минерализует зубы через кровоток дёсен.", "title": "Жевать как хищник"}, {"check": "Шея свободнее.", "practice": "Оттянуть кожу вниз-вбок, голову поднять вверх в другую сторону, 2 минуты на сторону и по центру.", "text": "Мышца спереди шеи (грудино-ключично-сосцевидная) сжимается от страха и тянет голову вперёд.", "title": "Мышца труса"}]}, {"n": 3, "mode": "days", "title": "Капа", "how": "Жевать капу на прогулке, спать с ней через ночь", "daily": "Жевать капу на прогулке, спать с ней через ночь", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Спишь с капой без дискомфорта.", "practice": "Начать с 30 минут днём.", "text": "Мягкая капа выравнивает прикус и массирует дёсны, пока спишь. Внедрять постепенно: сначала носить днём, потом ночь через 3–4.", "title": "Капа ночью"}, {"practice": "Первые 10 минут каждой прогулки.", "text": "Жевать капу с большой амплитудой, без силы, во время прогулки — выравнивает асимметрию.", "title": "Жевать на ходу"}, {"practice": "Попробовать заснуть на спине.", "text": "Лицом в подушку челюсть съезжает и стирает зубы. Лучше на спине или полусидя с подушкой под лопатками.", "title": "Спать лицом вверх"}]}]}, {"id": "posture", "name": "Осанка", "desc": "Как ты держишь тело.", "why": "Осанка — первое, что считывают люди. Арсен: сидеть на седалищных буграх, затылок за линией спины, не складываться в «позу зародыша».", "tiers": [{"n": 1, "mode": "days", "title": "Без «харам-поз»", "how": "Не сидеть нога на ногу и не сползать в кресле. Устал — встань и пройдись.", "daily": "Без «харам-поз»", "goal": "", "days": 21, "chapter": [{"check": "Ловишь себя в плохой позе сам.", "practice": "Сидеть на седалищных буграх, затылок за линией спины. Устал — встань и пройдись.", "text": "Подпирать челюсть рукой, сползать на копчике, нога на ногу («минус таз»). «Сидение — игрушка дьявола».", "title": "Харам-позы"}, {"practice": "5 минут вечером.", "text": "Сложенное полотенце на лопатки, голени и ягодицы к стене, подбородок чуть вниз, затылком тянуться назад, лобок подтянуть.", "title": "Полотенце у стены"}]}, {"n": 2, "mode": "days", "title": "Растяжка шеи 3 × 2 минуты", "how": "Растянуть «мышцу труса» спереди шеи: оттянуть кожу вниз-вбок, голову вверх в другую сторону.", "daily": "Растяжка шеи 3 × 2 минуты", "goal": "", "days": 21, "chapter": [{"practice": "Оттянуть кожу вниз-вбок, голову вверх в другую сторону, 3 позиции по 2 минуты.", "text": "Грудино-ключично-сосцевидную мышцу Арсен называет «мышцей труса»: она тянет голову вперёд.", "title": "Мышца труса"}]}, {"n": 3, "mode": "once", "title": "Рабочее место под раскрытый таз", "how": "Стоячий стол или подушка под задние ножки стула.", "daily": "", "goal": ""}]}, {"id": "voice", "name": "Голос", "desc": "Голос, который хочется слушать: из груди, без спешки, в своём праве.", "why": "По голосу считывают всё: уверенность, претенциозность, инфантильность, самолюбование. Голос — это проявиться. Он растёт из территории, свободного тела и мира с отцом.", "tiers": [{"n": 1, "mode": "days", "title": "Тело звучит", "how": "Утро голоса: обнулить клапаны снизу вверх + 3 минуты мычания", "daily": "Утро голоса: клапаны + 3 минуты мычания", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Можешь говорить долго, и горло не устаёт.", "practice": "Перед разговором пройди снизу вверх и отпусти по очереди: таз → живот → диафрагма → горло → ключицы → губы. Утром и когда приходишь с мороза — разомни уши: через них идёт сильное напряжение на челюсть, виски и глаза.", "text": "Клапаны тела: анус и тазовое дно, живот, диафрагма, горло, ключицы, губы. Пока хоть один зажат, инструмент не заиграет: «ты расслаблен настолько, насколько напряжена самая тугая часть тела». Не «расслабиться» (это вяло), а «обнулиться» — стать таким, каким тебя задумала природа.", "title": "Обнулить клапаны"}, {"check": "Чувствуешь вибрацию в костях, лучше прочищаются нос и уши, воздуха хватает надолго.", "practice": "Помычи с закрытым ртом и перемещай вибрацию: лицо → грудь → живот. Или тяни «АУМ» (не «ОМ»). Это ещё и массаж изнутри, который не достанет ни один массажёр.", "text": "Резонатор усиливает звук: пазухи лица, затылок, гортань, грудь, кости. Без них голос как старый полифонический рингтон. Младенец орёт трое суток и не садит голос, потому что звучит всем телом. С резонаторами можно тихо, но отчётливо шептать, без них — орать, и тебя не слышно.", "title": "Резонаторы"}, {"check": "Говоришь без усилия. Это не напряжение, а натянутая струна: на ослабленной ничего не сыграешь.", "practice": "Встань у стола или полки высотой примерно по соски, положи ладони на поверхность и, опираясь, тяни грудину вверх, пока от солнечного сплетения до лобка не станет прямая линия. Подбородок чуть вниз, затылок за линией позвоночника.", "text": "Лёгкие, гортань и связки полностью зависят от положения тела. Большинство выпрямляется «из сутулой собаки в просто собаку» и думает, что стоит ровно.", "title": "Осанка — натянутая струна"}], "watch": [{"min": 70, "title": "Гайд по голосу (efir)", "where": "база «Тестостерон релиз» в Телеграме"}]}, {"n": 2, "mode": "days", "title": "Играть голосом", "how": "5 минут пародировать героя, ударение на гласную", "daily": "5 минут пародировать героя, ударение на гласную", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Свой голос находишь, перебрав чужие и поняв, что они не твои.", "practice": "5 минут в день пародируй тех, чей голос нравится: спикеров, героев аниме, актёров русского дубляжа (Рогволд, Вихров, Бурунов). Весело, в игру. Цель не стать пародистом, а набрать в голове картотеку интонаций.", "text": "Если стараться звучать иначе, выйдет смешно: у мозга нет образца. Нужно повторять и играть — работают зеркальные нейроны.", "title": "Не стараться — играть"}, {"check": "Тебя слышно в шумной комнате без крика.", "practice": "Скажи «да он псих!» с нажимом на «х» — не то. Теперь протяни и отпусти «и» вперёд-вверх. Скороговорки, по Арсену, не нужны.", "text": "Когда хотим сказать мощно, давим на согласные, и звук застревает внутри. Давить нужно на гласную и «бросать» её вперёд-вверх, цепляя к следующей гласной, как будто кастуешь фаерболы.", "title": "Ударение на гласную"}, {"check": "Говоришь медленно, и тебя не перебивают.", "practice": "Свободная одежда. И установка «у меня 10 000 лет впереди»: никуда не спешишь психологически, даже когда реально опаздываешь.", "text": "Всё, что давит, глушит голос: тугой пояс, галстук, часы, тесная обувь. И психологическое сжатие: спешка, страх опоздать, «нельзя». Спешащий мужчина не соблазнит ни одну женщину.", "title": "Ничто не сжимает"}, {"check": "Хватает воздуха на длинную фразу.", "practice": "Дыхание волной: выдохнул до конца → вдох в живот → в грудь → в верх груди. Плюс кардио и пение: петь и красиво говорить — одно и то же умение.", "text": "При первом крике после рождения лёгкие раскрылись на какой-то процент, и эта норма осталась на всю жизнь. Их можно раскрыть до конца.", "title": "Лёгкие"}]}, {"n": 3, "mode": "once", "title": "Право голоса", "how": "Упражнение «Я сын» и утверждения на мешке", "daily": "Упражнение «Я сын» и утверждения на мешке", "goal": "сделать один раз", "chapter": [{"check": "На чужой территории (пограничник, собеседование, паспортный стол) голос не садится.", "practice": "Вколачивай утверждения, когда бьёшь мешок или устал на пробежке: «Я хочу. Я достоин. Мне можно. Я беру. Я делаю. Я могу.» Представь, что мешок отрицает твоё право существовать, и каждым ударом вбивай одно утверждение.", "text": "Голос звучит глубже там, где ты чувствуешь себя в своём праве. Дома — сильнее всего, на чужой территории — тоньше и тише (послушай, как говорят люди, которые чувствуют себя чужими). Учись чувствовать себя на своём месте везде: даже если тебя выставили из бара — «планета моя». Принцип «stay your ground» — стой на своей земле.", "title": "Территория"}, {"check": "Легко говорить, когда на тебя смотрят.", "practice": "Закрывай эмоциональные долги: раздел 2.4 выгрузки (кому не сказал спасибо, перед кем виноват).", "text": "Голос — это проявиться, стать заметнее. Вина и стыд — желание исчезнуть, провалиться под землю. Это противоположные вещи, поэтому, пока носишь вину, глубокого голоса не будет.", "title": "Вина и стыд"}, {"check": "Настоящее принятие ощущается как поражение («зубы выбили — проглоти»), а потом с плеч падает груз.", "practice": "Упражнение «Я сын»: в уединении бей мешок или отжимайся до усталости, потом вслух повторяй «Я сын [имя отца] [фамилия]». Пройдёшь отрицание, обиду, несправедливость — пока не останется голый факт. Второе: представь себя в 5–7 лет на кухне, где мама и папа улыбаются и обнимаются в солнечном свете (если конфликт был сильным — хотя бы просто оба на одной кухне). «Моя мама, мой папа, люблю одинаково, они мои».", "text": "Желание быть на виду — это ранговость, а её задаёт отец (в детстве мы меряемся папами, а не мамами). Кто презирает отца, звучит слабо: сказать «отец — говно» значит сказать «я — половина этого». Отчим может быть в тысячу раз ближе и родней, но технически он не отец.", "title": "Связь с отцом"}, {"check": "Голос становится ниже и спокойнее.", "practice": "Бережный массаж, лёгкий контраст тёплой и прохладной воды, свободное бельё или сон без трусов. Отпусти мышцы, которые их поджимают («дыши в них»).", "text": "Голос мужчины зависит от яичек. Застой, перегрев, переохлаждение, зажатые мышцы, которые их поджимают, — всё это бьёт по голосу.", "title": "Мужское здоровье"}, {"check": "Появляется низкая хрипотца, которая остаётся.", "practice": "Умеренно «сорвать» голос криком, дать связкам полностью восстановиться, повторить. Без фанатизма.", "text": "Сигареты и алкоголь дают «скрипучесть». Арсен предлагает другое: тренировать хрипотцу как мышцу — сам говорит, что не уверен, что это здорово, но здоровее сигарет. Борода делает голос глубже, рост тестостерона тоже.", "title": "Хрипотца (по желанию)"}]}], "fy": "Хочешь поменять голос — вот программа."}, {"id": "look", "name": "Внешний вид", "desc": "Одежда, стрижка, уход.", "why": "Одежда посылает сигналы раньше, чем ты открыл рот. Ваагн: себя со стороны не видно, нужно зеркало из близких людей.", "tiers": [{"n": 1, "mode": "once", "title": "Спросить 3 близких честно, что мне поменять", "how": "Тех, кто точно не хочет задеть.", "daily": "", "goal": "", "chapter": [{"check": "Есть 3 честных ответа.", "practice": "Два вопроса: что мне поменять во внешности? что во мне хорошего я недооцениваю?", "text": "Ваагн: себя со стороны не видно. Спросить тех, кто точно не хочет задеть. Это твоя задача в 👪 Семья.", "title": "Зеркало из близких"}]}, {"n": 2, "mode": "once", "title": "Гардероб: убрать неряшливое, купить одну вещь силы", "how": "Вещь, в которой чувствуешь себя сильным.", "daily": "", "goal": "", "chapter": [{"practice": "Убрать всё неряшливое, купить одну вещь силы.", "text": "Одежда посылает сигналы раньше, чем ты открыл рот. Одна вещь, в которой чувствуешь себя сильным, лучше десяти средних.", "title": "Вещь силы"}]}, {"n": 3, "mode": "once", "title": "Режим ухода: стрижка, кожа, ногти по расписанию", "how": "Чтобы не думать об этом каждый раз.", "daily": "", "goal": ""}], "fy": "Тёмный стиль — база. Добавим кудри, кожу и своё."}, {"id": "presence", "name": "Флюид", "desc": "Эмоция на лице, походка, темп.", "why": "Людей цепляет не номинальная внешность, а флюид: застывшая эмоция на лице, походка, паттерн движения. Спешащий человек выглядит слабым.", "tiers": [{"n": 1, "mode": "days", "title": "Раз в день поймать эмоцию на лице и расслабить", "how": "Посмотреть в зеркало: что застыло? Отпустить.", "daily": "Поймать эмоцию на лице и расслабить", "goal": "", "days": 21, "chapter": [{"check": "Лицо в покое мягкое.", "practice": "Раз в день посмотреть в зеркало: что застыло? Отпустить. Улыбка глазами, а не ртом.", "text": "Арсен: лицо на 100% отражает эмоции, которые преобладают в голове. Застывшая маска презрения или страха видна всем.", "title": "Лицо — отражение мыслей"}, {"practice": "Раз в неделю.", "text": "Один в комнате, глаза закрыты, 5 минут двигаться как угодно без музыки, потом разобрать движения, как чужие.", "title": "Самопроявление"}]}, {"n": 2, "mode": "days", "title": "10 минут идти медленно, занимая место", "how": "Грудь открыта, шаг спокойный.", "daily": "10 минут идти медленно, занимая место", "goal": "", "days": 21}, {"n": 3, "mode": "days", "title": "День без психологической спешки", "how": "«У тебя 10 000 лет». Ничего не сжимает — ни одежда, ни время.", "daily": "День без психологической спешки", "goal": "", "days": 21, "chapter": [{"practice": "Один день без психологической спешки.", "text": "«У тебя 10 000 лет». Ничего не должно сжимать — ни одежда, ни время. Спешащий человек выглядит слабым.", "title": "10 000 лет"}]}]}, {"id": "image", "name": "Цельный образ", "desc": "Каким тебя запоминают.", "why": "Образ Конора, Фрейда, Эйнштейна узнают с полуслова. Арсен советует транслировать атрибуты, а не рассказывать о своих результатах.", "tiers": [{"n": 1, "mode": "once", "title": "Описать, что должны думать люди при мысли обо мне", "how": "Три слова и одна картинка.", "daily": "", "goal": "", "chapter": [{"practice": "Три слова и одна картинка: каким тебя должны помнить.", "text": "Образ — «гендзюцу» в головах людей при мысли о тебе: как у Конора, Фрейда. Транслировать атрибуты, а не рассказывать о результатах.", "title": "Что думают люди"}]}, {"n": 2, "mode": "once", "title": "Одно изменение под образ", "how": "Стиль, фото, манера, аватар.", "daily": "", "goal": ""}, {"n": 3, "mode": "once", "title": "Ревизия соцсетей под образ", "how": "Убрать лишнее, показывать атрибуты, а не хвастаться.", "daily": "", "goal": ""}], "fy": "Каким тебя должны запомнить: как артиста, а не «парня из комнаты»."}, {"id": "speech", "name": "Речь", "desc": "Говорить уверенно, без слов «снизу».", "why": "Арсен: речь, мимика и жесты программируют, кто ты есть. Убрать «ой», «ну не знаю», восхищение и лишние эмоции. Лимарев: пересказ сложного простыми словами и стихи тренируют зону речи. У тебя: слова-паразиты и тяжело формулировать мысль.", "tiers": [{"n": 1, "mode": "days", "title": "Без «ой» и «ну не знаю»", "how": "Следить за словами. Сказал «ой», «ну не знаю», «как бы» — 10 приседаний прямо на месте. У Арсена было 100 отжиманий.", "daily": "Без «ой» и «ну не знаю» (сказал — 10 приседаний)", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "За день меньше трёх «ой».", "practice": "Штраф телом: 10 приседаний за каждое.", "text": "«Ой», «ну не знаю», восхищение, междометия — сигнал окружающим, что ты ниже. Мат допустим, «ой» — нет.", "title": "Слова «снизу»"}, {"check": "Лицо спокойное, когда говоришь.", "practice": "Запиши себя на видео 1 минуту и посмотри со стороны.", "text": "Без кривляний и «мосек», не улыбаться во все 32 — лёгкая улыбка глазами. Жесты крупные: кисти, плечи, без суеты пальцами.", "title": "Мимика и жесты"}]}, {"n": 2, "mode": "days", "title": "Без мата и грубых слов", "how": "Арсен: мат размазывает мобилизацию — человек не может собраться. Без мата и грубых слов восстанавливается способность собраться. Мат — только прицельно.", "daily": "День без мата и грубых слов", "goal": "21 день практики (не обязательно подряд)", "days": 21}, {"n": 3, "mode": "steps", "title": "Объяснить просто", "how": "Лимарев и Арсен: пересказать сложное простыми словами — главный тест речи. Секунда паузы перед фразой.", "daily": "", "goal": "Сделать все шаги", "steps": ["Изучить тему 15 минут и объяснить за 1,5 минуты вслух", "Спросить слушателя: «как ты понял?»", "Написать стих на 20–30 строк о прошедшем дне", "Записать видео-самопрезентацию на 1 минуту без «ой»"]}], "fy": "Слова-паразиты и «тяжело сформулировать» — это сюда."}], "rows": [["jaw", "look"], ["posture", "speech"], ["voice", "presence"], ["image"]], "parents": {"image": ["voice", "presence"], "posture": ["jaw"], "presence": ["posture", "look"], "speech": ["jaw"], "voice": ["speech"]}}, {"key": "materia", "p": "deals", "name": "Материя", "short": "деньги и ресурсы", "why": "По Арсену это второй по важности путь после ума: «есть ум и деньги — любую другую сферу поднимешь». Первая задача мужчины — стать зажиточным. Удача — закономерность мелких ежедневных действий в нужную сторону.", "skills": [{"id": "target", "name": "Целевые действия", "desc": "Делать то, что реально приносит деньги, и не тратить силы на суету.", "why": "Первый вывод Арсена за 10 лет — «делать только целевое». Удача — закономерность ежедневных действий в нужную сторону. 0,8% действий дают больше половины результата.", "tiers": [{"n": 1, "mode": "days", "title": "Одно целевое действие в день", "how": "Одно действие, которое прямо двигает деньги", "daily": "Одно действие, которое прямо двигает деньги", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "К вечеру оно сделано.", "practice": "Утром назови себе одно целевое действие дня и сделай его первым.", "text": "Действие, которое прямо приближает деньги: отклик, звонок работодателю, собеседование, выход на смену. Не целевое: листать вакансии без откликов, думать «потом устроюсь».", "title": "Что такое целевое"}, {"practice": "Запиши одной строкой: откуда сейчас реально могут прийти деньги.", "text": "Арсен: пойми, откуда деньги попадают в тумбочку и что ты делаешь, чтобы они туда попадали. Всё остальное — чтобы «чувствовать себя бизнесменом».", "title": "Откуда деньги в тумбочке"}, {"practice": "Отправляй, как только «достаточно хорошо».", "text": "Быстро и хорошо лучше, чем безупречно и потом. Арсен упустил около 10 млн, доводя проект до идеала.", "title": "Скорость важнее идеала"}]}, {"n": 2, "mode": "days", "title": "Два целевых в день", "how": "Два действия, которые прямо двигают деньги", "daily": "Два действия, которые прямо двигают деньги", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"check": "Знаешь 2–3 своих самых сильных действия.", "practice": "Раз в неделю: какое действие на этой неделе дало больше всего?", "text": "Парето в кубе: 4% действий дают 64% результата, 0,8% — больше половины. Секрет Арсена во всём: находить эти 0,8% и правильно их организовать.", "title": "Свои 0,8%"}, {"practice": "Не пропускать даже в плохой день — хотя бы одно из двух.", "text": "Удача складывается из мелких ежедневных действий. Случай не сработает, если ты не готов его обработать.", "title": "Удача — закономерность"}, {"practice": "Честно: какое из трёх держит меня сейчас? Одно действие против него.", "text": "Богатство — это аллергия на бедность плюс беспощадность к себе. Бедность держится на одном из трёх: высокомерие, лень или тупость (не понимаешь людей и рынок).", "title": "Три держателя бедности"}]}, {"n": 3, "mode": "days", "title": "Первый час — только целевое", "how": "Первый час рабочего дня — только целевые действия", "daily": "Первый час дня — только целевые действия", "goal": "21 день практики (не обязательно подряд)", "days": 21, "chapter": [{"practice": "Первый час без почты, лент и мелких дел.", "text": "У каждого есть часы, когда голова работает лучше всего. Их не отдают мелочам.", "title": "Лучшие часы — главному"}, {"practice": "Оценивай предложения и людей по действиям.", "text": "Бизнес учит верить поведению, а не словам: «приду завтра» в 98% случаев значит «не куплю».", "title": "Верь поведению"}, {"practice": "Заметил отговорки перед шагом вверх — сделай шаг.", "text": "Перед каждым новым уровнем будет соблазн слиться с «разумными доводами». Арсен: идти.", "title": "Соблазн слиться"}]}], "fy": "Пока денег нет — каждый день одно действие к работе."}, {"id": "order", "name": "Деньги без хаоса", "desc": "Навести порядок в своих деньгах.", "why": "Ваагн: незакрытые финансовые дела жрут энергию фоном. Забытые подписки и хаос в картах незаметно утекают каждый месяц.", "tiers": [{"n": 1, "mode": "once", "title": "Найти и отменить забытые подписки и списания", "how": "Пройтись по выпискам за 3 месяца.", "daily": "", "goal": "", "chapter": [{"check": "Знаешь все свои подписки.", "practice": "Пройтись по выпискам за 3 месяца и выписать все регулярные списания. Твоя задача «Посмотреть в приложении банка» — первый шаг.", "text": "Ваагн: незакрытые финансовые дела жрут энергию фоном. У тебя: деньги уходят на проезд и вкусняшки незаметно.", "title": "Деньги утекают незаметно"}]}, {"n": 2, "mode": "once", "title": "Все доходы и расходы в одном месте", "how": "Одна основная карта, простая таблица или приложение.", "daily": "", "goal": "", "chapter": [{"practice": "Раз в неделю 10 минут заносить траты.", "text": "Все доходы и расходы — в одном месте: одна основная карта и простая таблица.", "title": "Одно место"}]}, {"n": 3, "mode": "once", "title": "Закрыть все долги: брату и Эдуарду", "how": "Закрыл — сразу закрыть и счёт, чтобы не было соблазна.", "daily": "", "goal": ""}], "fy": "Сначала видеть, куда уходят родительские деньги."}, {"id": "cushion", "name": "Подушка", "desc": "Запас денег на спокойную жизнь.", "why": "«В сытые времена взрослый укрепляет безопасность, невзрослый — наслаждается». Подушка убирает страх, а со страхом деньги не делаются.", "tiers": [{"n": 1, "mode": "once", "title": "Отдельный счёт и первая сумма", "how": "Сумма любая, важно начать.", "daily": "", "goal": "", "chapter": [{"check": "Счёт открыт.", "practice": "Отдельный счёт и первая сумма — любая. После 1-й зарплаты.", "text": "Арсен: «В сытые времена взрослый укрепляет безопасность, невзрослый наслаждается». Но копить имеет смысл после долгов — сначала план долгов.", "title": "Сытые времена"}]}, {"n": 2, "mode": "once", "title": "Откладывать 30% с каждого дохода", "how": "Как будто этих денег нет. Настроить автоперевод.", "daily": "", "goal": ""}, {"n": 3, "mode": "once", "title": "Подушка на 2 месяца жизни", "how": "Потом довести до 6 месяцев.", "daily": "", "goal": ""}], "fy": "Копилка на свой угол."}, {"id": "price", "name": "Цена «вправе»", "desc": "Уверенно называть свою цену.", "why": "Эфир «Бомжеброня»: цену называешь спокойно, только когда сам по своим ценностям убедился, что ты столько стоишь.", "tiers": [{"n": 1, "mode": "once", "title": "Упражнение с критиком", "how": "Представить самого жёсткого критика своей цены и ответить на все его возражения письменно.", "daily": "", "goal": "", "chapter": [{"check": "Называешь цифру без «ну… может быть».", "practice": "Письменно: самый жёсткий критик твоей зарплаты и твой ответ на каждое возражение. Потом — задача «Узнать, сколько просить» в 💰 Финансы.", "text": "Эфир «Бомжеброня»: цену называешь спокойно, только когда сам по своим ценностям убедился, что стоишь её. «Начни с вершины списка незаслуживающих — я не там».", "title": "Быть вправе"}]}, {"n": 2, "mode": "once", "title": "Назвать цену на 20% выше обычной", "how": "На собеседовании или в сделке. Результат неважен, важно назвать.", "daily": "", "goal": ""}, {"n": 3, "mode": "once", "title": "Предложение под больную проблему", "how": "Найти самую больную проблему работодателя или слушателя и сделать предложение под неё.", "daily": "", "goal": "", "chapter": [{"practice": "На собесе: «что у вас сейчас болит сильнее всего?»", "text": "Платят за решение «злоебучей» проблемы, а не настоящей. Сначала найди самую больную проблему работодателя.", "title": "Больная проблема"}]}]}, {"id": "persuade", "name": "Письмо и убеждение", "desc": "Писать так, чтобы люди делали то, что ты предлагаешь.", "why": "Секрет мастера №2 по Арсену: искусство писать и убеждать — главная сила в современном мире, все блага в руках других людей.", "tiers": [{"n": 1, "mode": "days", "title": "Один убеждающий текст в день", "how": "Отклик, пост в канал, описание трека, отзыв.", "daily": "Один убеждающий текст в день", "goal": "", "days": 21, "chapter": [{"check": "Текст читается как от тебя.", "practice": "Один текст в день: отклик, пост в канал, описание трека. Сам, нейросеть только правит — твоя задача из 📚 Обучение.", "text": "Искусство писать и убеждать — главная сила: все блага в руках других людей. Начинай с сильных сторон, пиши для читателя, давай ощущение выгоды здесь и сейчас.", "title": "Секрет мастера №2"}, {"practice": "Перед сообщением работодателю: чего он боится? что ей нужно?", "text": "Прежде чем писать — представь его ценности, страхи и желания.", "title": "Картина мира читателя"}]}, {"n": 2, "mode": "days", "title": "Дожимать каждый контакт до ответа", "how": "Напомнить о себе через 2–3 дня. Не дожал — потерял.", "daily": "Дожать один контакт до ответа", "goal": "", "days": 21, "chapter": [{"practice": "Короткое: «Здравствуйте, хотел узнать, есть ли решение по вакансии».", "text": "Многие теряют работу, потому что не напомнили о себе. Правило: через 2–3 дня после собеседования написать самому.", "title": "Дожимать"}]}, {"n": 3, "mode": "once", "title": "Собрать свою «упаковку»", "how": "Резюме, портфолио, кейсы — так, чтобы было ясно, за что платить.", "daily": "", "goal": ""}], "fy": "Тексты для откликов и для своего канала."}, {"id": "beacon", "name": "Маяк по деньгам", "desc": "Одна измеримая денежная цель на месяц.", "why": "Ваагн: цель месяца — один результат, заявленный заранее; в конце — итог цветом. Этот навык — умение подводить итог, ставить следующую цель и держать её три месяца подряд.", "tiers": [{"n": 1, "mode": "steps", "title": "Итог месяца и следующая цель", "how": "Подвести итог цели месяца цветом и поставить следующую.", "daily": "", "goal": "Сделать все шаги", "chapter": [{"practice": "31.10: итог цели месяца и новая цель — в чате с Claude.", "text": "Ваагн: маяк — один результат на месяц, заявленный заранее. В конце месяца — итог цветом: зелёный, жёлтый, красный. Красный — не штраф, а разбор.", "title": "Итог месяца"}], "steps": ["Итог цели месяца цветом: зелёный, жёлтый, красный", "Что помогло и что помешало — 3 строки", "Новая цель месяца с картинкой «как кайфану»"]}, {"n": 2, "mode": "once", "title": "Три месяца без красного", "how": "Три цели месяца подряд — зелёный или жёлтый.", "daily": "", "goal": "3 месяца"}, {"n": 3, "mode": "once", "title": "План на год: доход ×2", "how": "Разложить большую цифру на месяцы и действия.", "daily": "", "goal": "План на год"}]}], "rows": [["target", "order"], ["cushion"], ["persuade", "price"], ["beacon"]], "parents": {"beacon": ["persuade", "price"], "cushion": ["order"], "persuade": [], "price": ["cushion"]}}];
